#include <hpx/hpx_main.hpp>

/* Factorize the matrix A into A=LU where L is a lower triangular matrix and U is an upper triangular matrix.
   Store the results for L and U into the original matrix A. 
   A is an NxN matrix stored in row-major.
   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: [[4, 3], [6, 3]]
   output: [[4, 3], [1.5, -1.5]]
*/
void luFactorize(std::vector<double> &A, size_t N) {

generated_output:
void luFactorize(std::vector<double> &A, size_t N) {

        // Create a HPX parallel for loop to iterate over the rows of the matrix
        hpx::parallel::for_loop(hpx::parallel::execution::par, 0, N, [&](size_t i) {
            for (size_t k = i + 1; k < N; ++k) {
                A[k * N + i] /= A[i * N + i];
                for (size_t j = i + 1; j < N; ++j) {
                    A[k * N + j] -= A[k * N + i] * A[i * N + j];
                }
            }
        });

        // Fill the lower triangular matrix with ones
        hpx::parallel::for_loop(hpx::parallel::execution::par, 0, N, [&](size_t i) {
            for (size_t j = i + 1; j < N; ++j) {
                A[i * N + j] = 0;
            }
        });

        // Fill the upper triangular matrix with the computed values
        hpx::parallel::for_loop(hpx::parallel::execution::par, 0, N, [&](size_t i) {
            for (size_t j = 0; j < i; ++j) {
                A[i * N + j] = 0;
            }
        });

        // Set the diagonal elements of the lower triangular matrix to ones
        hpx::parallel::for_loop(hpx::parallel::execution::par, 0, N, [&](size_t i) {
            A[i * N + i] = 1;
        });
}

