void luFactorize(std::vector<double> &A, size_t N) {

        // Implementing LU factorization using HPX
        hpx::parallel::for_loop(0, N, 1, [&](size_t i) {
            for(size_t k = i; k < N; ++k) {
                double sum = 0;
                for(size_t j = 0; j < i; ++j) {
                    sum += A[i*N + j] * A[j*N + k];
                }
                A[i*N + k] -= sum;
            }

            for(size_t k = i+1; k < N; ++k) {
                double sum = 0;
                for(size_t j = 0; j < i; ++j) {
                    sum += A[k*N + j] * A[j*N + i];
                }
                A[k*N + i] = (A[k*N + i] - sum) / A[i*N + i];
            }
        });

        // Making the lower triangular matrix
        for(size_t i = 0; i < N; ++i) {
            for(size_t j = i+1; j < N; ++j) {
                A[j*N + i] = 0;
            }
        }

        // Making the upper triangular matrix
        for(size_t i = 0; i < N; ++i) {
            for(size_t j = 0; j < i; ++j) {
                A[i*N + j] = 0;
            }
        }
}

