void luFactorize(std::vector<double> &A, size_t N) {

        // Create a HPX parallel for loop to iterate over the rows of the matrix
        hpx::parallel::for_loop(0, N, 1, [&](size_t i) {
            // For each row, iterate over the columns
            for (size_t j = i; j < N; ++j) {
                // Compute the sum of A[i][k]*A[k][j] for k from 0 to i-1
                double sum = 0.0;
                for (size_t k = 0; k < i; ++k) {
                    sum += A[i*N + k] * A[k*N + j];
                }
                // Store the result in A[i][j]
                A[i*N + j] -= sum;
            }

            // For each row, iterate over the columns again
            for (size_t j = i+1; j < N; ++j) {
                // Compute the sum of A[i][k]*A[k][j] for k from 0 to i-1
                double sum = 0.0;
                for (size_t k = 0; k < i; ++k) {
                    sum += A[i*N + k] * A[k*N + j];
                }
                // Store the result in A[i][j]
                A[i*N + j] = (A[i*N + j] - sum) / A[i*N + i];
            }
        });

        // Create a HPX parallel for loop to iterate over the rows of the matrix
        hpx::parallel::for_loop(0, N, 1, [&](size_t i) {
            // For each row, iterate over the columns
            for (size_t j = 0; j < i; ++j) {
                // Compute the sum of A[i][k]*A[k][j] for k from 0 to i-1
                double sum = 0.0;
                for (size_t k = 0; k < j; ++k) {
                    sum += A[i*N + k] * A[k*N + j];
                }
                // Store the result in A[i][j]
                A[i*N + j] = (A[i*N + j] - sum) / A[j*N + j];
            }
        });
}

