void luFactorize(std::vector<double> &A, size_t N) {

        // This is a simple implementation of LU factorization using HPX.
        // It assumes that the input matrix is square and has been initialized.
        // The LU factorization is performed in-place, meaning the original matrix is modified.
        // The L matrix is stored in the lower triangular part of the matrix, and the U matrix is stored in the upper triangular part.
        // The diagonal elements of the L matrix are set to 1.

        hpx::parallel::for_loop(hpx::parallel::execution::par, 0, N, [&](size_t i) {
            for (size_t j = i + 1; j < N; ++j) {
                A[j * N + i] /= A[i * N + i];
                for (size_t k = i + 1; k < N; ++k) {
                    A[j * N + k] -= A[j * N + i] * A[i * N + k];
                }
            }
        });

        // Set the diagonal elements of the L matrix to 1
        hpx::parallel::for_loop(hpx::parallel::execution::par, 0, N, [&](size_t i) {
            A[i * N + i] = 1;
        });
}

