/* Factorize the matrix A into A=LU where L is a lower triangular matrix and U is an upper triangular matrix.
   Store the results for L and U into the original matrix A. 
   A is an NxN matrix stored in row-major.
   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: [[4, 3], [6, 3]]
   output: [[4, 3], [1.5, -1.5]]
*/
void luFactorize(std::vector<double> &A, size_t N) {

generated_output:
void luFactorize(std::vector<double> &A, size_t N) {

        // Create HPX parallel execution policy
        hpx::parallel::execution::parallel_executor exec;

        // Create HPX parallel for loop to iterate over the rows of the matrix
        hpx::parallel::for_loop(exec, 0, N, [&](size_t i) {
            // Iterate over the columns of the matrix
            for (size_t j = i; j < N; ++j) {
                // Compute the sum of the products of the elements in the ith row and jth column
                double sum = 0.0;
                for (size_t k = 0; k < i; ++k) {
                    sum += A[i * N + k] * A[k * N + j];
                }
                // Store the result in the ith row and jth column of the matrix
                A[i * N + j] -= sum;
            }

            // Iterate over the rows below the ith row
            for (size_t j = i + 1; j < N; ++j) {
                // Compute the sum of the products of the elements in the ith row and jth column
                double sum = 0.0;
                for (size_t k = 0; k < i; ++k) {
                    sum += A[j * N + k] * A[k * N + i];
                }
                // Store the result in the jth row and ith column of the matrix
                A[j * N + i] = (A[j * N + i] - sum) / A[i * N + i];
            }
        });

        // Create HPX parallel for loop to iterate over the rows of the matrix
        hpx::parallel::for_loop(exec, 0, N, [&](size_t i) {
            // Iterate over the columns of the matrix
            for (size_t j = i + 1; j < N; ++j) {
                // Compute the sum of the products of the elements in the ith row and jth column
                double sum = 0.0;
                for (size_t k = 0; k < i; ++k) {
                    sum += A[i * N + k] * A[k * N + j];
                }
                // Store the result in the ith row and jth column of the matrix
                A[i * N + j] -= sum;
            }
        });
}

