        // It assumes that the input matrix A is stored in row-major order.
        // The LU factorization is performed in-place, meaning that the resulting L and U matrices are stored in the original matrix A.

        // Create a parallel execution policy
        hpx::parallel::execution::parallel_executor exec;

        // Iterate over the rows of the matrix
        for (size_t i = 0; i < N; ++i) {
            // Compute the pivot
            double pivot = A[i*N + i];

            // Compute the LU factorization in parallel
            hpx::parallel::transform(exec, A.begin() + i*N + i + 1, A.begin() + (i+1)*N, A.begin() + i*N + i + 1,
                [=](double x) {
                    return x / pivot;
                });

            // Update the remaining elements in the row
            for (size_t j = i + 1; j < N; ++j) {
                double factor = A[j*N + i];
                for (size_t k = i; k < N; ++k) {
                    A[j*N + k] -= factor * A[i*N + k];
                }
            }
        }
}

