        // Create a vector of HPX actions
        std::vector<hpx::future<void>> futures;

        // Iterate over the rows of the matrix
        for (size_t i = 0; i < N; ++i) {
            // Create a HPX action for each row
            futures.push_back(hpx::async([&A, &b, &x, i, N]() {
