        // Create HPX actions for matrix operations
        auto mat_mul = hpx::parallel::execution::parallel_reduce(exec, A.begin(), A.end(), 0.0,
            [&](double a, double b) { return a + b; });

        auto mat_inv = hpx::parallel::execution::parallel_reduce(exec, A.begin(), A.end(), 0.0,
            [&](double a, double b) { return a * b; });

        // Compute x = A^-1 * b
        hpx::parallel::execution::parallel_for_each(exec, A.begin(), A.end(),
            [&](double a) {
                x.push_back(a / mat_inv);
            });

        // Compute residual b - Ax
        hpx::parallel::execution::parallel_for_each(exec, A.begin(), A.end(),
            [&](double a) {
                b.push_back(a - mat_mul);
