void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

        // Create HPX parallel execution policy
        hpx::parallel::execution::parallel_executor exec;

        // Create HPX actions for matrix operations
        auto matrix_multiply = hpx::parallel::execution::parallel_reduce(exec, A.begin(), A.end(), 0.0,
            [&](std::vector<double>::const_iterator first, std::vector<double>::const_iterator last, double init) {
                return std::inner_product(first, last, b.begin(), init);
            },
            std::plus<double>());

        auto matrix_inverse = hpx::parallel::execution::parallel_reduce(exec, A.begin(), A.end(), 0.0,
            [&](std::vector<double>::const_iterator first, std::vector<double>::const_iterator last, double init) {
                return std::inner_product(first, last, b.begin(), init);
            },
            std::plus<double>());

        // Compute x = A^-1 * b
        std::transform(matrix_multiply.begin(), matrix_multiply.end(), matrix_inverse.begin(), x.begin(), std::divides<double>());
