void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

        // Create HPX parallel execution policy
        hpx::parallel::execution::parallel_executor exec;

        // Compute the LU decomposition of A
        std::vector<double> LU(N*N);
        for (size_t i = 0; i < N; ++i) {
            for (size_t j = 0; j < N; ++j) {
                double sum = 0.0;
                for (size_t k = 0; k < j; ++k) {
                    sum += LU[i*N + k] * LU[k*N + j];
                }
                LU[i*N + j] = (i == j)? 1 : (A[i*N + j] - sum);
            }
            for (size_t j = i + 1; j < N; ++j) {
                double sum = 0.0;
                for (size_t k = 0; k < i; ++k) {
                    sum += LU[i*N + k] * LU[k*N + j];
                }
                LU[i*N + j] = (A[i*N + j] - sum) / LU[i*N + i];
            }
        }

        // Compute the y vector
        std::vector<double> y(N);
        for (size_t i = 0; i < N; ++i) {
            double sum = 0.0;
            for (size_t j = 0; j < i; ++j) {
                sum += LU[i*N + j] * y[j];
            }
            y[i] = b[i] - sum;
        }

        // Compute the x vector
        for (size_t i = N; i-- > 0;) {
            double sum = 0.0;
            for (size_t j = i + 1; j < N; ++j) {
                sum += LU[i*N + j] * x[j];
            }
            x[i] = (y[i] - sum) / LU[i*N + i];
        }
}

