void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

        // Create a vector of vectors to represent the matrix A
        std::vector<std::vector<double>> matrixA(N, std::vector<double>(N));
        for (size_t i = 0; i < N; ++i) {
            for (size_t j = 0; j < N; ++j) {
                matrixA[i][j] = A[i * N + j];
            }
        }

        // Create a vector to represent the vector b
        std::vector<double> vectorB(b);

        // Create a vector to represent the vector x
        std::vector<double> vectorX(N);

        // Create a parallel execution policy
        hpx::parallel::execution::parallel_executor exec;

        // Use HPX to solve the linear system in parallel
        hpx::parallel::transform(exec, matrixA.begin(), matrixA.end(), vectorB.begin(), vectorX.begin(),
