/* Solve the linear system Ax=b for x.
   A is an NxN matrix in row-major. x and b have N elements.
   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: A=[[1,4,2], [1,2,3], [2,1,3]] b=[11, 11, 13]
   output: x=[3, 1, 2]
*/
void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

        // Create a parallel execution policy
        hpx::parallel::execution::parallel_executor exec;

        // Create a HPX task that computes the solution
        hpx::future<void> task = hpx::async(exec, [&]() {
            // Perform Gaussian elimination
            for (size_t i = 0; i < N; ++i) {
                // Partial pivoting
                size_t maxRow = i;
                for (size_t k = i + 1; k < N; ++k) {
                    if (std::abs(A[k * N + i]) > std::abs(A[maxRow * N + i])) {
                        maxRow = k;
                    }
                }
                if (maxRow!= i) {
                    // Swap rows i and maxRow
                    for (size_t k = i; k < N; ++k) {
                        std::swap(A[i * N + k], A[maxRow * N + k]);
                    }
                    std::swap(b[i], b[maxRow]);
                }

                // Eliminate the elements below the pivot
                for (size_t k = i + 1; k < N; ++k) {
                    double factor = A[k * N + i] / A[i * N + i];
                    for (size_t j = i; j < N; ++j) {
                        A[k * N + j] -= factor * A[i * N + j];
                    }
                    b[k] -= factor * b[i];
                }
            }

            // Back substitution
            for (size_t i = N; i-- > 0;) {
                x[i] = b[i];
                for (size_t j = i + 1; j < N; ++j) {
                    x[i] -= A[i * N + j] * x[j];
                }
                x[i] /= A[i * N + i];
            }
        });

        // Wait for the task to complete
        task.get();
}

