void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

        // Create a parallel execution policy
        hpx::parallel::execution::parallel_executor exec;

        // Create a HPX task to perform the matrix-vector multiplication
        hpx::future<std::vector<double>> future = hpx::async(exec, [&]() {
            std::vector<double> result(N);
            for (size_t i = 0; i < N; ++i) {
                for (size_t j = 0; j < N; ++j) {
                    result[i] += A[i * N + j] * b[j];
                }
            }
            return result;
        });

        // Wait for the task to complete and get the result
        x = future.get();
}

