#include <hpx/hpx_main.hpp>

/* Solve the linear system Ax=b for x.
   A is an NxN matrix in row-major. x and b have N elements.
   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: A=[[1,4,2], [1,2,3], [2,1,3]] b=[11, 11, 13]
   output: x=[3, 1, 2]
*/
void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

        // Create HPX parallel execution policy
        hpx::parallel::execution::parallel_executor exec;

        // Create HPX actions for matrix-vector multiplication and vector addition
        auto matvec_action = hpx::actions::make_ready_future_on(exec, [](std::vector<double> const& A, std::vector<double> const& x) {
            std::vector<double> result(x.size(), 0.0);
            for (size_t i = 0; i < x.size(); ++i) {
                for (size_t j = 0; j < x.size(); ++j) {
                    result[i] += A[i * x.size() + j] * x[j];
                }
            }
            return result;
        });

        auto vecadd_action = hpx::actions::make_ready_future_on(exec, [](std::vector<double> const& x, std::vector<double> const& y) {
            std::vector<double> result(x.size(), 0.0);
            for (size_t i = 0; i < x.size(); ++i) {
                result[i] = x[i] + y[i];
            }
            return result;
        });

        // Initialize x with b
        x = b;

        // Perform Gauss-Seidel iteration
        for (size_t k = 0; k < N; ++k) {
            // Compute Ax
            auto Ax = matvec_action(A, x);

            // Compute residual b - Ax
            std::vector<double> residual(b.size(), 0.0);
            for (size_t i = 0; i < b.size(); ++i) {
                residual[i] = b[i] - Ax[i];
            }

            // Compute x = x + residual
            x = vecadd_action(x, residual);
        }
}

