   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: A=[[1,4,2], [1,2,3], [2,1,3]] b=[11, 11, 13]
   output: x=[3, 1, 2]
*/
void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

        // Create HPX parallel execution policy
        hpx::parallel::execution::parallel_executor exec;

        // Create HPX actions for the matrix-vector multiplication and vector addition
        auto mat_vec_mult = [](std::vector<double> const& A, std::vector<double> const& x) {
            std::vector<double> result(x.size(), 0.0);
            for (size_t i = 0; i < x.size(); ++i) {
                for (size_t j = 0; j < x.size(); ++j) {
                    result[i] += A[i * x.size() + j] * x[j];
                }
            }
            return result;
        };

        auto vec_add = [](std::vector<double> const& x, std::vector<double> const& y) {
            std::vector<double> result(x.size(), 0.0);
            for (size_t i = 0; i < x.size(); ++i) {
                result[i] = x[i] + y[i];
            }
            return result;
        };

        // Create HPX actions for the Gaussian elimination
        auto gaussian_elimination = [](std::vector<double> const& A, std::vector<double> const& b, size_t N) {
            std::vector<double> x(N, 0.0);
            for (size_t i = 0; i < N; ++i) {
                x[i] = b[i];
                for (size_t j = 0; j < i; ++j) {
                    x[i] -= A[i * N + j] * x[j];
                }
                x[i] /= A[i * N + i];
            }
            return x;
        };

        // Compute the solution in parallel
        x = hpx::parallel::transform_reduce(exec, b.begin(), b.end(), A.begin(), 0.0, std::plus<double>(), mat_vec_mult);
        x = hpx::parallel::transform_reduce(exec, x.begin(), x.end(), b.begin(), 0.0, std::plus<double>(), vec_add);
        x = hpx::parallel::transform_reduce(exec, A.begin(), A.end(), b.begin(), 0.0, std::plus<double>(), gaussian_elimination);
}

