void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

        // Create HPX parallel execution space
        hpx::parallel::execution::parallel_executor exec;

        // Create HPX parallel execution policy
        hpx::parallel::execution::parallel_executor_policy policy(exec);

        // Create HPX parallel execution task
        hpx::parallel::execution::parallel_task<void> task(policy, [&](hpx::parallel::execution::parallel_executor_policy const& policy) {

            // Forward elimination
            for (size_t k = 0; k < N; ++k) {
                // Pivot
                size_t maxIndex = k;
                for (size_t i = k + 1; i < N; ++i) {
                    if (std::abs(A[i * N + k]) > std::abs(A[maxIndex * N + k])) {
                        maxIndex = i;
                    }
                }

                // Swap rows
                if (maxIndex!= k) {
                    for (size_t j = 0; j < N; ++j) {
                        std::swap(A[k * N + j], A[maxIndex * N + j]);
                        std::swap(b[k], b[maxIndex]);
                    }
                }

                // Eliminate
                for (size_t i = k + 1; i < N; ++i) {
                    double factor = A[i * N + k] / A[k * N + k];
                    for (size_t j = k + 1; j < N; ++j) {
                        A[i * N + j] -= factor * A[k * N + j];
                    }
                    b[i] -= factor * b[k];
                }
            }

            // Backward substitution
            for (size_t i = N; i-- > 0;) {
                x[i] = b[i];
                for (size_t j = i + 1; j < N; ++j) {
                    x[i] -= A[i * N + j] * x[j];
                }
                x[i] /= A[i * N + i];
            }
        });

        // Execute the task
        task.execute();

        // Wait for the task to finish
        task.wait();
}

