        // The Gaussian elimination method is a method for solving systems of linear scalar equations.
        // It consists of a sequence of operations that transforms the coefficient matrix into an upper triangular matrix.
        // The solution is then found by back-substitution.

        // First, we need to create a parallel execution policy.
        hpx::parallel::execution::parallel_executor exec;

        // Then, we need to create a vector of indices for the rows of the matrix.
        std::vector<size_t> indices(N);
        std::iota(indices.begin(), indices.end(), 0);

