                }
                b_copy[k] -= factor * b_copy[i];
            }
        });

        // We need to perform back-substitution in parallel.
        hpx::parallel::for_each(exec, indices.rbegin(), indices.rend(), [&](size_t i) {
            x[i] = b_copy[i];
            for (size_t j = i + 1; j < N; ++j) {
                x[i] -= A_copy[i][j] * x[j];
            }
            x[i] /= A_copy[i][i];
        });
}

