void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

        // Implement the Gaussian elimination method to solve the linear system.
        // This method involves forward and backward substitution.
        // First, we perform the forward elimination.
        for (size_t k = 0; k < N; ++k) {
            // Find the pivot row.
            size_t pivot = k;
            for (size_t i = k + 1; i < N; ++i) {
                if (std::abs(A[i * N + k]) > std::abs(A[pivot * N + k])) {
                    pivot = i;
                }
            }

            // Swap the pivot row with the current row.
            if (pivot!= k) {
                std::swap_ranges(A.begin() + k * N, A.begin() + (k + 1) * N, A.begin() + pivot * N);
