            }

            // Perform the forward elimination.
            for (size_t i = k + 1; i < N; ++i) {
                double factor = A[i * N + k] / A[k * N + k];
                for (size_t j = k + 1; j < N; ++j) {
                    A[i * N + j] -= factor * A[k * N + j];
                }
                b[i] -= factor * b[k];
            }
        }

        // Then, we perform the backward substitution.
        for (size_t i = N; i-- > 0;) {
            x[i] = b[i];
