void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

        // Create a parallel execution policy
        hpx::parallel::execution::parallel_executor exec;

        // Create a HPX task to perform the Gaussian elimination
        auto task = hpx::parallel::execution::parallel_reduce(
            exec,
            hpx::parallel::execution::par,
            0,
            N,
            0.0,
            [&](hpx::parallel::execution::parallel_reduce_args<double> const& args, double init) {
                size_t i = args.get_this_index();
                double sum = init;
                for (size_t j = 0; j < N; ++j) {
                    sum += A[i * N + j] * x[j];
                }
                return sum - b[i];
            },
            [](double a, double b) {
                return a + b;
            }
        );

        // Wait for the task to complete
        double residual = task.get();

        // If the residual is not zero, the system is not solvable
        if (residual!= 0) {
            throw std::runtime_error("The system is not solvable");
        }
