void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

        // Create a parallel execution policy
        hpx::parallel::execution::parallel_executor exec;

        // Create a vector of indices for the rows of the matrix
        std::vector<size_t> indices(N);
        std::iota(indices.begin(), indices.end(), 0);

        // Create a vector of indices for the columns of the matrix
        std::vector<size_t> col_indices(N);
        std::iota(col_indices.begin(), col_indices.end(), 0);

        // Create a vector of results for the matrix
        std::vector<double> results(N);

        // Create a vector of results for the vector b
        std::vector<double> b_results(N);

        // Create a vector of results for the vector x
        std::vector<double> x_results(N);

        // Use HPX to compute the matrix A and vector b
        hpx::parallel::for_each(exec, indices.begin(), indices.end(), [&](size_t i) {
            results[i] = A[i*N + i];
            b_results[i] = b[i];
        });

        // Use HPX to compute the matrix A^-1 and vector b
        hpx::parallel::for_each(exec, indices.begin(), indices.end(), [&](size_t i) {
            b_results[i] /= results[i];
            for (size_t j = 0; j < N; ++j) {
                if (i!= j) {
                    b_results[i] -= A[i*N + j] * b_results[j] / results[i];
                }
            }
        });

        // Use HPX to compute the vector x
        hpx::parallel::for_each(exec, indices.begin(), indices.end(), [&](size_t i) {
            x_results[i] = b_results[i];
        });

        // Copy the results back to the original vectors
        std::copy(x_results.begin(), x_results.end(), x.begin());
}

