#include <hpx/hpx_main.hpp>

/* Multiply the matrix A by the matrix B. Store the results in the matrix C.
   A is an MxK matrix, B is a KxN matrix, and C is a MxN matrix. The matrices are stored in row-major.
   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: A=[[1, -1, 2], [0, -2, 1]] B=[[4, 1], [-1, 0], [2, 2]]
   output: C=[[9, 5], [4, 2]]
*/
void gemm(std::vector<double> const& A, std::vector<double> const& B, std::vector<double> &C, size_t M, size_t K, size_t N) {

generated_output:
void gemm(std::vector<double> const& A, std::vector<double> const& B, std::vector<double> &C, size_t M, size_t K, size_t N) {

        // Create HPX parallel execution policy
        hpx::parallel::execution::parallel_executor exec;

        // Create HPX actions for matrix multiplication
        auto mul_action = [](std::vector<double> const& A, std::vector<double> const& B, std::vector<double> &C, size_t M, size_t K, size_t N, size_t i, size_t j) {
            double sum = 0;
            for(size_t k = 0; k < K; ++k) {
                sum += A[i*K + k] * B[k*N + j];
            }
            C[i*N + j] = sum;
        };

        // Create HPX futures for each element in C
        std::vector<hpx::future<void>> futures;
        for(size_t i = 0; i < M; ++i) {
            for(size_t j = 0; j < N; ++j) {
                futures.push_back(hpx::async(exec, mul_action, A, B, C, M, K, N, i, j));
            }
        }

        // Wait for all futures to complete
        for(auto& f : futures) {
            f.get();
        }
}

