/* Multiply the matrix A by the vector x. Store the results in the vector y.
   A is an MxN matrix, x has N elements, and y has M elements.
   Use HPX to compute in parallel. Assume HPX has already been initialized. 
   Example:

   input: A=[[1, -1, 2], [0, -3, 1]] x=[2, 1, 0]
   output: y=[1, -3]
*/
void gemv(std::vector<double> const& A, std::vector<double> const& x, std::vector<double> &y, size_t M, size_t N) {

generated_output:
void gemv(std::vector<double> const& A, std::vector<double> const& x, std::vector<double> &y, size_t M, size_t N) {

        // Create a vector of HPX futures
        std::vector<hpx::future<double>> futures;

        // Iterate over the rows of the matrix A
        for(size_t i = 0; i < M; ++i) {
            // Create a HPX future that computes the dot product of the i-th row of A and x
            futures.push_back(hpx::async([i, &A, &x, N]() {
                double result = 0.0;
                for(size_t j = 0; j < N; ++j) {
                    result += A[i*N + j] * x[j];
                }
                return result;
            }));
        }

        // Wait for all futures to complete and store the results in y
        for(size_t i = 0; i < M; ++i) {
            y[i] = futures[i].get();
        }
}

