void gemv(std::vector<double> const& A, std::vector<double> const& x, std::vector<double> &y, size_t M, size_t N) {

        // Create a vector of futures to hold the results of the parallel computations
        std::vector<hpx::future<double>> results(M);

        // Define the HPX action to perform the multiplication
        auto gemv_action = [](std::vector<double> const& A, std::vector<double> const& x, size_t M, size_t N, size_t i) {
            double result = 0;
            for (size_t j = 0; j < N; ++j) {
                result += A[i * N + j] * x[j];
            }
            return result;
