            }
            return result;
        };

        // Launch the parallel computations
        for (size_t i = 0; i < M; ++i) {
            results[i] = hpx::async(gemv_action, A, x, M, N, i);
        }

        // Wait for the computations to complete and store the results
        for (size_t i = 0; i < M; ++i) {
            y[i] = results[i].get();
        }
}

