void gemv(std::vector<double> const& A, std::vector<double> const& x, std::vector<double> &y, size_t M, size_t N) {

        // Create a vector of HPX shared_ptr to double
        std::vector<hpx::shared_ptr<double>> A_shared(A.size());
        std::vector<hpx::shared_ptr<double>> x_shared(x.size());
        std::vector<hpx::shared_ptr<double>> y_shared(y.size());

        // Copy the data from A, x, y to the shared_ptr
        for (size_t i = 0; i < A.size(); ++i) {
            A_shared[i] = hpx::make_shared<double>(A[i]);
        }
        for (size_t i = 0; i < x.size(); ++i) {
            x_shared[i] = hpx::make_shared<double>(x[i]);
        }
        for (size_t i = 0; i < y.size(); ++i) {
            y_shared[i] = hpx::make_shared<double>(0);
        }

        // Define the HPX parallel for loop
        hpx::parallel::for_loop(
            hpx::parallel::execution::par,
            0, M,
            [&](size_t i) {
                double sum = 0;
                for (size_t j = 0; j < N; ++j) {
                    sum += *A_shared[i * N + j] * *x_shared[j];
                }
                *y_shared[i] = sum;
            }
        );

        // Copy the results back to y
        for (size_t i = 0; i < y.size(); ++i) {
            y[i] = *y_shared[i];
        }
}

