void gemv(std::vector<double> const& A, std::vector<double> const& x, std::vector<double> &y, size_t M, size_t N) {

        // Create a vector of HPX futures
        std::vector<hpx::future<double>> futures;

        // Iterate over the rows of the matrix
        for (size_t i = 0; i < M; ++i) {
            // Create a HPX action to compute the dot product of the i-th row of A and x
            auto dot_product = hpx::async([i, &A, &x, N]() {
                double sum = 0.0;
                for (size_t j = 0; j < N; ++j) {
                    sum += A[i * N + j] * x[j];
                }
                return sum;
            });

            // Add the future to the vector
            futures.push_back(std::move(dot_product));
        }

        // Wait for all futures to complete and store the results in y
        for (size_t i = 0; i < M; ++i) {
            y[i] = futures[i].get();
        }
}

