   Example:

   input: A=[{0,0,1}, {0,1,1}, {1,1,-2}] b=[1,4]
   output: x=[3,-2]
*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

        // Initialize x with zeros
        x.resize(N, 0.0);

        // Create a vector to store the diagonal elements of A
        std::vector<double> diag(N, 0.0);

        // Compute the diagonal elements and store them in diag
        for (auto const& a : A) {
            if (a.row == a.column) {
                diag[a.row] = a.value;
            }
        }

        // Compute the right-hand side vector rhs
        std::vector<double> rhs(N, 0.0);
        for (size_t i = 0; i < N; ++i) {
            for (auto const& a : A) {
                if (a.row == i) {
                    rhs[i] += a.value * b[a.column];
                }
            }
        }

        // Parallelize the computation of x
        hpx::parallel::for_loop(
            hpx::parallel::execution::par,
            0, N,
            [&](size_t i) {
                x[i] = rhs[i] / diag[i];
            }
        );
}

