void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

        // Create a vector of vectors to represent the sparse matrix
        std::vector<std::vector<std::pair<size_t, double>>> matrix(N);

        // Fill the matrix with the COO elements
        for (auto const& element : A) {
            matrix[element.row].emplace_back(element.column, element.value);
        }

        // Create a vector to hold the results
        x.resize(N);

        // Use HPX to parallelize the computation
        hpx::parallel::for_loop(hpx::parallel::execution::par, 0, N, [&](size_t i) {
            double sum = 0;
            for (auto const& pair : matrix[i]) {
                sum += pair.second * b[pair.first];
            }
            x[i] = sum;
        });
}

