        // Initialize x to zero
        x.resize(N, 0.0);

        // Compute the diagonal elements of A
        std::vector<double> diag(N, 0.0);
        for (auto const& a : A) {
            if (a.row == a.column) {
                diag[a.row] = a.value;
            }
        }

        // Compute the non-diagonal elements of A
        std::vector<std::pair<size_t, double>> non_diag(N);
        for (auto const& a : A) {
            if (a.row!= a.column) {
