        hpx::parallel::for_loop(0, N, [&](size_t i) {
            double sum = b[i];
            for (size_t j = 0; j < N; ++j) {
                if (j!= i) {
                    sum -= non_diag[i].second * x[j];
                }
            }
            x[i] = sum / diag[i];
        });
}

