void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

        // Create a parallel execution policy
        hpx::parallel::execution::parallel_executor exec;

        // Initialize x with zeros
        x.resize(N, 0);

        // Create a vector of pairs to hold the row indices and their corresponding values
        std::vector<std::pair<size_t, double>> row_values(N);

        // Iterate over the COO elements
        for (auto const& element : A) {
            // Add the value to the corresponding row in the row_values vector
            row_values[element.row].second += element.value;
        }

        // Parallelize the computation of x
        hpx::parallel::for_each(exec,
            hpx::parallel::execution::par,
            hpx::parallel::execution::chunk_size(1),
            hpx::parallel::execution::static_chunks,
            0, N,
            [&](size_t i) {
                double sum = 0;
                for (auto const& element : A) {
                    if (element.row == i) {
                        sum += element.value * b[element.column];
                    }
                }
                x[i] = (b[i] - sum) / row_values[i].second;
            });
}

