   Example:

   input: A=[{0,0,1}, {0,1,1}, {1,1,-2}] b=[1,4]
   output: x=[3,-2]
*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

        // Initialize x to 0
        x.resize(N, 0);

        // Compute the diagonal elements of A
        std::vector<double> diag(N, 0);
        for (auto const& element : A) {
            if (element.row == element.column) {
                diag[element.row] = element.value;
            }
        }

        // Compute the off-diagonal elements of A
        std::vector<double> off_diag(N, 0);
        for (auto const& element : A) {
            if (element.row!= element.column) {
                off_diag[element.row] += element.value;
            }
        }

        // Compute the LU decomposition of A
        std::vector<double> L(N*N, 0);
        std::vector<double> U(N*N, 0);
        for (size_t i = 0; i < N; ++i) {
            L[i*N+i] = 1;
            U[i*N+i] = diag[i];
            for (size_t j = 0; j < i; ++j) {
                L[i*N+j] = off_diag[i] / U[j*N+j];
                U[i*N+j] = 0;
            }
            for (size_t j = i+1; j < N; ++j) {
                L[i*N+j] = 0;
                U[i*N+j] = off_diag[i] / U[j*N+j];
            }
        }

        // Compute the y vector
        std::vector<double> y(N, 0);
        for (size_t i = 0; i < N; ++i) {
            y[i] = b[i];
            for (size_t j = 0; j < i; ++j) {
                y[i] -= L[i*N+j] * y[j];
            }
        }

        // Compute the x vector
        for (size_t i = N; i-- > 0;) {
            x[i] = y[i];
            for (size_t j = i+1; j < N; ++j) {
                x[i] -= U[i*N+j] * x[j];
            }
            x[i] /= U[i*N+i];
        }
}

