void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

        // Initialize x with zeros
        x.resize(N, 0.0);

        // Compute the sum of each row in A
        std::vector<double> row_sum(N, 0.0);
        for (auto const& element : A) {
            row_sum[element.row] += element.value;
        }

        // Compute the sum of each column in A
        std::vector<double> col_sum(N, 0.0);
        for (auto const& element : A) {
            col_sum[element.column] += element.value;
        }

        // Compute the diagonal elements of A
        std::vector<double> diagonal(N, 0.0);
        for (auto const& element : A) {
            if (element.row == element.column) {
                diagonal[element.row] = element.value;
            }
        }

        // Compute the x vector in parallel using HPX
        hpx::parallel::for_loop(hpx::parallel::execution::par, 0, N, [&](size_t i) {
            double sum = 0.0;
            for (auto const& element : A) {
                if (element.row == i) {
                    sum += element.value * x[element.column];
                }
            }
            x[i] = (b[i] - sum) / diagonal[i];
        });
}

