void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

        // Initialize x with zeros
        x.resize(N, 0.0);

        // Create a vector of pairs to store the non-zero elements of A
        std::vector<std::pair<size_t, double>> A_non_zero;
        A_non_zero.reserve(A.size());

        // Fill A_non_zero with the non-zero elements of A
        for (auto const& element : A) {
            A_non_zero.emplace_back(element.row * N + element.column, element.value);
        }

        // Sort A_non_zero by row
        std::sort(A_non_zero.begin(), A_non_zero.end());

        // Create a vector to store the result of the parallel computation
        std::vector<double> result(N, 0.0);

        // Compute the result in parallel using HPX
        hpx::parallel::for_loop(hpx::parallel::execution::par, 0, N, [&](size_t i) {
            double sum = 0.0;
            for (auto it = A_non_zero.begin(); it!= A_non_zero.end(); ++it) {
                if (it->first / N!= i) {
                    break;
                }
                sum += it->second * x[it->first % N];
            }
            result[i] = (b[i] - sum) / A_non_zero[i * N].second;
        });

        // Copy the result back to x
        x = result;
}

