   Example:

   input: A=[{0,0,1}, {0,1,1}, {1,1,-2}] b=[1,4]
   output: x=[3,-2]
*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

        // Initialize the x vector with zeros
        x.resize(N, 0);

        // Compute the diagonal elements of the matrix A
        std::vector<double> diag(N, 0);
        for (auto const& element : A) {
            if (element.row == element.column) {
                diag[element.row] = element.value;
            }
        }

        // Compute the off-diagonal elements of the matrix A
        std::vector<std::pair<size_t, double>> offDiag(N);
        for (auto const& element : A) {
            if (element.row!= element.column) {
                offDiag[element.row].first = element.column;
                offDiag[element.row].second = element.value;
            }
        }

        // Compute the solution x in parallel using HPX
        hpx::parallel::for_loop(
            hpx::parallel::execution::par,
            0, N,
            [&](size_t i) {
                double sum = b[i];
                for (size_t j = 0; j < N; ++j) {
                    if (j!= i) {
                        sum -= offDiag[j].second * x[j];
                    }
                }
                x[i] = sum / diag[i];
            }
        );
}

