   Example:

   input: A=[{0,0,1}, {0,1,1}, {1,1,-2}] b=[1,4]
   output: x=[3,-2]
*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

        // Initialize x with zeros
        x.resize(N, 0.0);

        // Compute the diagonal elements of A
        std::vector<double> diag(N, 0.0);
        for (auto const& a : A) {
            if (a.row == a.column) {
                diag[a.row] = a.value;
            }
        }

        // Compute the LU decomposition of A
        std::vector<double> L(N*N, 0.0);
        std::vector<double> U(N*N, 0.0);
        for (size_t i = 0; i < N; ++i) {
            for (size_t j = 0; j < N; ++j) {
                if (i == j) {
                    L[i*N + j] = 1.0;
                    U[i*N + j] = diag[i];
                } else if (i < j) {
                    double sum = 0.0;
                    for (size_t k = 0; k < i; ++k) {
                        sum += L[i*N + k] * U[k*N + j];
                    }
                    U[i*N + j] = A[i*N + j] - sum;
                    L[i*N + j] = 0.0;
                } else {
                    double sum = 0.0;
                    for (size_t k = 0; k < j; ++k) {
                        sum += L[i*N + k] * U[k*N + j];
                    }
                    L[i*N + j] = (A[i*N + j] - sum) / U[j*N + j];
                    U[i*N + j] = 0.0;
                }
            }
        }

        // Compute the solution of Ly=b
        std::vector<double> y(N, 0.0);
        for (size_t i = 0; i < N; ++i) {
            double sum = 0.0;
            for (size_t k = 0; k < i; ++k) {
                sum += L[i*N + k] * y[k];
            }
            y[i] = b[i] - sum;
        }

        // Compute the solution of Ux=y
        for (int i = N-1; i >= 0; --i) {
            double sum = 0.0;
            for (int k = i+1; k < N; ++k) {
                sum += U[i*N + k] * x[k];
            }
            x[i] = (y[i] - sum) / U[i*N + i];
        }
}

