        x.resize(N, 0.0);

        // Create a vector of vectors to hold the non-zero elements of A
        std::vector<std::vector<COOElement>> A_non_zero(N);

        // Fill A_non_zero with the non-zero elements of A
        for (auto const& element : A) {
            A_non_zero[element.row].push_back(element);
