   Example:

   input: A=[{0,0,1}, {0,1,1}, {1,1,-2}] b=[1,4]
   output: x=[3,-2]
*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

        // Create a vector of vectors to hold the sparse matrix in CSR format
        std::vector<std::vector<COOElement>> CSR(N);

        // Convert the COO matrix to CSR
        for (auto const& element : A) {
            CSR[element.row].push_back(element);
        }

        // Create a vector to hold the diagonal elements of the matrix
        std::vector<double> diagonal(N);

        // Compute the diagonal elements and store them in the diagonal vector
        for (size_t i = 0; i < N; ++i) {
            for (auto const& element : CSR[i]) {
                if (element.row == element.column) {
                    diagonal[i] = element.value;
                    break;
                }
            }
        }

        // Create a vector to hold the right-hand side of the system
        std::vector<double> rhs(N);

        // Compute the right-hand side of the system
        for (size_t i = 0; i < N; ++i) {
            for (auto const& element : CSR[i]) {
                if (element.row!= element.column) {
                    rhs[i] += element.value * b[element.column];
                }
            }
        }

        // Create a vector to hold the solution
        x.resize(N);

        // Compute the solution using Gaussian elimination
        for (size_t i = 0; i < N; ++i) {
            x[i] = (rhs[i] - rhs[i] * diagonal[i]) / diagonal[i];
        }
}

