void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

        // Create a vector of COOElement to store the transpose of A
        std::vector<COOElement> At(A.size());

        // Transpose A
        hpx::parallel::transform(hpx::parallel::execution::par, A.begin(), A.end(), At.begin(),
            [N](COOElement const& a) {
                return COOElement{a.column, a.row, a.value};
            });

        // Create a vector of double to store the diagonal elements of A
        std::vector<double> diagonal(N, 0.0);

        // Compute the diagonal elements of A
        hpx::parallel::for_each(hpx::parallel::execution::par, At.begin(), At.end(),
            [&diagonal](COOElement const& a) {
                if (a.row == a.column) {
                    diagonal[a.row] = a.value;
                }
            });

        // Create a vector of double to store the result of Ax
        std::vector<double> Ax(N, 0.0);

        // Compute Ax
        hpx::parallel::transform(hpx::parallel::execution::par, At.begin(), At.end(), b.begin(), Ax.begin(),
            [&diagonal](COOElement const& a, double const& b) {
                return a.row == a.column? a.value * b : 0.0;
            });

        // Compute x
        hpx::parallel::transform(hpx::parallel::execution::par, Ax.begin(), Ax.end(), diagonal.begin(), x.begin(),
            [](double const& a, double const& b) {
                return a / b;
            });
}

