   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: A=[{0,0,1}, {0,1,1}, {1,1,-2}] b=[1,4]
   output: x=[3,-2]
*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

        // Initialize x with zeros
        x.resize(N, 0.0);

        // Compute the diagonal elements of A
        std::vector<double> diag(N, 0.0);
        for (auto const& element : A) {
            if (element.row == element.column) {
                diag[element.row] += element.value;
            }
        }

        // Compute the off-diagonal elements of A
        std::vector<std::pair<size_t, double>> offDiag(N);
        for (auto const& element : A) {
            if (element.row!= element.column) {
                offDiag[element.row].first = element.column;
                offDiag[element.row].second += element.value;
            }
        }

        // Compute the right-hand side vector b
        std::vector<double> rhs(N, 0.0);
        for (size_t i = 0; i < N; ++i) {
            for (auto const& element : A) {
                if (element.row == i) {
                    rhs[i] += element.value * b[element.column];
                }
            }
        }

        // Solve the system using Gaussian elimination
        for (size_t i = 0; i < N; ++i) {
            double diagEl = diag[i];
            if (diagEl == 0.0) {
                throw std::runtime_error("Matrix is singular");
            }
            rhs[i] /= diagEl;
            diag[i] = 1.0;
            if (offDiag[i].first!= std::numeric_limits<size_t>::max()) {
                offDiag[i].second /= diagEl;
            }
            for (size_t j = i + 1; j < N; ++j) {
                double offDiagEl = offDiag[j].second;
                if (offDiagEl!= 0.0) {
                    rhs[j] -= offDiagEl * rhs[i];
                    diag[j] -= offDiagEl * diag[i];
                    if (offDiag[j].first!= std::numeric_limits<size_t>::max()) {
                        offDiag[j].second -= offDiagEl * offDiag[i].second;
                    }
                }
            }
        }

        // Back-substitution
        for (size_t i = N; i-- > 0;) {
            x[i] = rhs[i];
            for (size_t j = 0; j < i; ++j) {
                x[j] -= offDiag[j].second * x[i];
            }
        }
}

