        // Compute the diagonal elements of A
        std::vector<double> diag(N, 0.0);
        for (auto const& element : A) {
            if (element.row == element.column) {
                diag[element.row] += element.value;
            }
        }

        // Compute the off-diagonal elements of A
        std::vector<std::pair<size_t, double>> offDiag(N);
        for (auto const& element : A) {
            if (element.row!= element.column) {
