            [&](size_t i) {
                double sum = b[i];
                for (size_t j = 0; j < N; ++j) {
                    if (j!= i) {
                        sum -= offDiag[j].second * x[j];
                    }
                }
                x[i] = sum / diag[i];
            }
        );
