                    nonDiagonal[i] = element.value;
                    break;
                }
            }
        }

        // Create a vector to store the right-hand side vector
        std::vector<double> rhs(N);

        // Compute the right-hand side vector
        for (size_t i = 0; i < N; ++i) {
            rhs[i] = b[i];
        }

        // Use HPX to parallelize the computation of the solution vector
        hpx::parallel::for_loop(hpx::parallel::execution::par, 0, N, [&](size_t i) {
            double sum = 0.0;
            for (size_t j = 0; j < N; ++j) {
                if (i!= j) {
                    sum += nonDiagonal[j] * x[j];
                }
            }
            x[i] = (rhs[i] - sum) / diagonal[i];
        });
