void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

        // Create a vector of vectors to hold the sparse matrix in CSR format
        std::vector<std::vector<COOElement>> CSR(N);

        // Convert COO to CSR
        for (const auto& element : A) {
            CSR[element.row].push_back(element);
        }

        // Create a vector to hold the diagonal elements of the matrix
        std::vector<double> diagonal(N);

        // Compute the diagonal elements and the right-hand side vector
        for (size_t i = 0; i < N; ++i) {
            double diagonal_element = 0.0;
            for (const auto& element : CSR[i]) {
                if (element.column == i) {
                    diagonal_element = element.value;
                    break;
                }
            }
            diagonal[i] = diagonal_element;
        }

        // Create a vector to hold the result
        x.resize(N);

        // Solve the system in parallel using HPX
        hpx::parallel::for_loop(hpx::parallel::execution::par, 0, N, [&](size_t i) {
            double sum = 0.0;
            for (const auto& element : CSR[i]) {
                if (element.column!= i) {
                    sum += element.value * x[element.column];
                }
            }
            x[i] = (b[i] - sum) / diagonal[i];
        });
}

