void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

        // Create a parallel execution policy
        hpx::parallel::execution::parallel_executor exec;

        // Initialize x with zeros
        x.resize(N, 0.0);

        // Create a vector of pairs to hold the row indices and the corresponding values
        std::vector<std::pair<size_t, double>> row_values(N);

        // Loop over the COO elements
        hpx::parallel::for_each(exec, A.begin(), A.end(), [&](COOElement const& element) {
            // Add the value to the corresponding row index in the row_values vector
            row_values[element.row].second += element.value;
        });

        // Loop over the COO elements again
        hpx::parallel::for_each(exec, A.begin(), A.end(), [&](COOElement const& element) {
            // Calculate the new value for the corresponding row index in the x vector
            x[element.row] -= element.value * b[element.column] / row_values[element.row].second;
        });
}

