   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: A=[{0,0,1}, {0,1,1}, {1,1,-2}] b=[1,4]
   output: x=[3,-2]
*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

        // Initialize x to zero
        x.resize(N, 0);

        // Create a vector of pairs to hold the non-zero elements of A
        std::vector<std::pair<size_t, double>> A_non_zero;
        A_non_zero.reserve(A.size());

        // Convert A from COO format to CSR format
        for (auto const& element : A) {
            A_non_zero.emplace_back(element.column, element.value);
        }

        // Sort the non-zero elements by row
        std::sort(A_non_zero.begin(), A_non_zero.end(), [](auto const& a, auto const& b) {
            return a.first < b.first;
        });

        // Compute the solution in parallel using HPX
        hpx::parallel::for_loop(0, N, [&](size_t i) {
            double sum = 0;
            for (auto it = A_non_zero.begin(); it!= A_non_zero.end(); ++it) {
                if (it->first > i) {
                    break;
                }
                sum += it->second * x[it->first];
            }
            x[i] = (b[i] - sum) / A_non_zero[i].second;
        });
}

