void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

        // Initialize the x vector with zeros
        x.resize(N, 0.0);

        // Create a vector to store the diagonal elements of A
        std::vector<double> diag(N, 0.0);

        // Create a vector to store the non-diagonal elements of A
        std::vector<COOElement> nonDiag;

        // Split A into diagonal and non-diagonal elements
        for (auto const& element : A) {
            if (element.row == element.column) {
                diag[element.row] = element.value;
            } else {
                nonDiag.push_back(element);
            }
        }

        // Create a vector to store the result of the forward substitution
        std::vector<double> y(N, 0.0);

        // Perform the forward substitution
        hpx::parallel::for_loop(hpx::parallel::execution::par, 0, N, [&](size_t i) {
            double sum = 0.0;
            for (auto const& element : nonDiag) {
                if (element.row == i) {
                    sum += element.value * y[element.column];
                }
            }
            y[i] = (b[i] - sum) / diag[i];
        });

        // Create a vector to store the result of the backward substitution
        std::vector<double> x_temp(N, 0.0);

        // Perform the backward substitution
        hpx::parallel::for_loop(hpx::parallel::execution::par, 0, N, [&](size_t i) {
            double sum = 0.0;
            for (auto const& element : nonDiag) {
                if (element.column == i) {
                    sum += element.value * x_temp[element.row];
                }
            }
            x_temp[i] = y[i] - sum;
        });

        // Copy the result from x_temp to x
        x = x_temp;
}

