void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

        // Create a vector of vectors to represent the sparse matrix in CSR format
        std::vector<std::vector<COOElement>> CSR(N);

        // Convert COO to CSR
        for (auto const& element : A) {
            CSR[element.row].push_back(element);
        }

        // Create a vector to store the diagonal elements of the matrix
        std::vector<double> diag(N);

        // Create a vector to store the non-diagonal elements of the matrix
        std::vector<double> off_diag(N);

        // Compute the diagonal and off-diagonal elements of the matrix
        for (size_t i = 0; i < N; ++i) {
            for (auto const& element : CSR[i]) {
                if (element.row == element.column) {
                    diag[i] = element.value;
                } else {
                    off_diag[element.row] += element.value;
                }
            }
        }

        // Create a vector to store the solution
        std::vector<double> y(N);

        // Compute the solution using Gaussian elimination
        for (size_t i = 0; i < N; ++i) {
            y[i] = b[i] - off_diag[i];
            y[i] /= diag[i];
        }

        // Compute the solution using back substitution
        for (int i = N - 1; i >= 0; --i) {
            x[i] = y[i];
            for (int j = 0; j < i; ++j) {
                x[j] -= x[i] * off_diag[j];
            }
            x[i] /= diag[i];
        }
}

