   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: A=[{0,0,1}, {0,1,1}, {1,1,-2}] b=[1,4]
   output: x=[3,-2]
*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

        // Initialize x to zero
        x.resize(N, 0.0);

        // Compute the diagonal elements of A
        std::vector<double> diag(N, 0.0);
        for (auto const& elem : A) {
            if (elem.row == elem.column) {
                diag[elem.row] = elem.value;
            }
        }

        // Compute the LU decomposition of A
        std::vector<double> L(N*N, 0.0);
        std::vector<double> U(N*N, 0.0);
        for (size_t i = 0; i < N; ++i) {
            for (size_t j = 0; j < N; ++j) {
                if (i == j) {
                    L[i*N + j] = 1.0;
                } else if (i < j) {
                    double sum = 0.0;
                    for (size_t k = 0; k < i; ++k) {
                        sum += L[i*N + k] * U[k*N + j];
                    }
                    L[i*N + j] = (A[i*N + j] - sum) / U[i*N + i];
                } else {
                    double sum = 0.0;
                    for (size_t k = 0; k < j; ++k) {
                        sum += L[i*N + k] * U[k*N + j];
                    }
                    U[i*N + j] = A[i*N + j] - sum;
                }
            }
        }

        // Compute the y vector
        std::vector<double> y(N, 0.0);
        for (size_t i = 0; i < N; ++i) {
            double sum = 0.0;
            for (size_t j = 0; j < i; ++j) {
                sum += L[i*N + j] * y[j];
            }
            y[i] = b[i] - sum;
        }

        // Compute the x vector
        for (int i = N-1; i >= 0; --i) {
            double sum = 0.0;
            for (int j = N-1; j > i; --j) {
                sum += U[i*N + j] * x[j];
            }
            x[i] = (y[i] - sum) / U[i*N + i];
        }
}

