void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

        // Create a vector of vectors to represent the sparse matrix in CSR format
        std::vector<std::vector<COOElement>> CSR(N);
        for (auto const& element : A) {
            CSR[element.row].push_back(element);
        }

        // Create a vector to store the diagonal elements of the matrix
        std::vector<double> diag(N);

        // Create a vector to store the result of the matrix-vector multiplication
        std::vector<double> result(N);

        // Compute the diagonal elements and the result of the matrix-vector multiplication in parallel
        hpx::parallel::for_loop(hpx::parallel::execution::par, 0, N, [&](size_t i) {
            double sum = 0.0;
            for (auto const& element : CSR[i]) {
