void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

        // Create a vector of vectors to represent the sparse matrix in CSR format
        std::vector<std::vector<COOElement>> CSR(N);

        // Convert COO to CSR
        for (auto const& element : A) {
            CSR[element.row].push_back(element);
        }

        // Create a vector to store the diagonal elements of the matrix
        std::vector<double> diagonal(N);

        // Create a vector to store the non-diagonal elements of the matrix
        std::vector<double> off_diagonal(N);

        // Create a vector to store the right-hand side vector
        std::vector<double> rhs(N);

        // Parallelize the computation of the diagonal and off-diagonal elements and the right-hand side vector
        hpx::parallel::for_loop(hpx::parallel::execution::par, 0, N, [&](size_t i) {
            double diagonal_element = 0.0;
            double off_diagonal_element = 0.0;
            double rhs_element = 0.0;

            for (auto const& element : CSR[i]) {
                if (element.row == element.column) {
                    diagonal_element += element.value;
                } else {
                    off_diagonal_element += element.value;
                }
                rhs_element += element.value * b[element.column];
            }

            diagonal[i] = diagonal_element;
            off_diagonal[i] = off_diagonal_element;
            rhs[i] = rhs_element;
        });

        // Solve the system of equations using Gaussian elimination
        for (size_t i = 0; i < N; ++i) {
            double diagonal_element = diagonal[i];
            double off_diagonal_element = off_diagonal[i];
            double rhs_element = rhs[i];

            for (size_t j = 0; j < i; ++j) {
                double off_diagonal_element_j = off_diagonal[j];
                double diagonal_element_j = diagonal[j];
                double rhs_element_j = rhs[j];

                double factor = off_diagonal_element_j / diagonal_element;
                off_diagonal[j] -= factor * off_diagonal_element;
                rhs[j] -= factor * rhs_element;
            }

            x[i] = rhs_element / diagonal_element;
        }
}

