        x.resize(N, 0);

        // Create a vector to store the diagonal elements of A
        std::vector<double> diag(N, 0);

        // Create a vector to store the non-diagonal elements of A
        std::vector<double> non_diag(N, 0);

        // Parallel for loop to calculate the diagonal and non-diagonal elements of A
        hpx::parallel::for_loop(hpx::parallel::execution::par, 0, N, [&](size_t i) {
            for (auto const& elem : A) {
                if (elem.row == i) {
                    if (elem.column == i) {
                        diag[i] += elem.value;
                    } else {
                        non_diag[i] += elem.value;
                    }
                }
            }
        });

        // Parallel for loop to calculate the solution x
