void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

        // Initialize x with zeros
        x.resize(N, 0.0);

        // Compute the diagonal elements of A
        std::vector<double> diag(N, 0.0);
        for (auto const& elem : A) {
            if (elem.row == elem.column) {
                diag[elem.row] = elem.value;
            }
        }

        // Compute the rest of the elements of A
        std::vector<std::vector<double>> rest(N, std::vector<double>(N, 0.0));
        for (auto const& elem : A) {
            if (elem.row!= elem.column) {
                rest[elem.row][elem.column] = elem.value;
            }
        }

        // Compute the inverse of the diagonal elements of A
        std::vector<double> invDiag(N, 0.0);
        for (size_t i = 0; i < N; ++i) {
            if (diag[i]!= 0.0) {
                invDiag[i] = 1.0 / diag[i];
            }
        }

        // Compute the solution x
        hpx::parallel::for_loop(0, N, [&](size_t i) {
            double sum = 0.0;
            for (size_t j = 0; j < N; ++j) {
                sum += rest[i][j] * x[j];
            }
            x[i] = (b[i] - sum) * invDiag[i];
        });
}

