   Example:

   input: A=[{0,0,1}, {0,1,1}, {1,1,-2}] b=[1,4]
   output: x=[3,-2]
*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

        // Create a vector of vectors to hold the matrix in CSR format
        std::vector<std::vector<COOElement>> CSR(N);

        // Convert the COO matrix to CSR
        for (auto const& element : A) {
            CSR[element.row].push_back(element);
        }

        // Create a vector to hold the diagonal elements of the matrix
        std::vector<double> diag(N);

        // Create a vector to hold the right-hand side vector
        std::vector<double> rhs(N);

        // Create a vector to hold the solution vector
        std::vector<double> solution(N);

        // Compute the diagonal and right-hand side vector
        for (size_t i = 0; i < N; ++i) {
            for (auto const& element : CSR[i]) {
                if (element.row == element.column) {
                    diag[i] = element.value;
                } else {
                    rhs[i] += element.value * b[element.column];
                }
            }
        }

        // Solve the system of equations using Gaussian elimination
        for (size_t i = 0; i < N; ++i) {
            rhs[i] /= diag[i];
            for (size_t j = i + 1; j < N; ++j) {
                rhs[j] -= rhs[i] * CSR[j][i].value;
            }
        }

        // Back-substitution
        for (size_t i = N; i-- > 0;) {
            solution[i] = rhs[i];
            for (size_t j = 0; j < i; ++j) {
                solution[j] -= solution[i] * CSR[j][i].value;
            }
        }

        // Copy the solution vector to the output
        x = solution;
}

