   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: A=[{0,0,1}, {0,1,1}, {1,1,-2}] b=[1,4]
   output: x=[3,-2]
*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

        // Initialize x with zeros
        x.resize(N, 0.0);

        // Compute the diagonal elements of the matrix A
        std::vector<double> diag(N, 0.0);
        for(auto const& elem : A) {
            if(elem.row == elem.column) {
                diag[elem.row] = elem.value;
            }
        }

        // Compute the off-diagonal elements of the matrix A
        std::vector<std::pair<size_t, double>> off_diag(N);
        for(auto const& elem : A) {
            if(elem.row!= elem.column) {
                off_diag[elem.row].first = elem.column;
                off_diag[elem.row].second = elem.value;
            }
        }

        // Solve the linear system in parallel using HPX
        hpx::parallel::for_loop(hpx::parallel::execution::par, 0, N, [&](size_t i) {
            double sum = b[i];
            for(size_t j = 0; j < N; ++j) {
                if(j!= i) {
                    sum -= off_diag[j].second * x[off_diag[j].first];
                }
            }
            x[i] = sum / diag[i];
        });
}

