   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: A=[{0,0,1}, {0,1,1}, {1,1,-2}] b=[1,4]
   output: x=[3,-2]
*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

        // Initialize x to zero
        x.resize(N, 0.0);

        // Create a vector of pairs to hold the row and column indices and values
        std::vector<std::pair<std::pair<size_t, size_t>, double>> coo_elements;
        for (auto const& element : A) {
            coo_elements.push_back({{element.row, element.column}, element.value});
        }

        // Sort the vector of pairs by row and column indices
        std::sort(coo_elements.begin(), coo_elements.end());

        // Use HPX to parallelize the computation
        hpx::parallel::for_loop(hpx::parallel::execution::par, 0, N, [&](size_t i) {
            double sum = 0.0;
            for (auto const& element : coo_elements) {
                if (element.first.first == i) {
                    sum += element.second * x[element.first.second];
                }
            }
            x[i] = (b[i] - sum) / coo_elements[i].second;
        });
}

