void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

        // Create a vector of vectors to represent the sparse matrix in CSR format
        std::vector<std::vector<COOElement>> CSR(N);

        // Convert COO to CSR
        for (auto const& element : A) {
            CSR[element.row].push_back(element);
        }

        // Create a vector to store the diagonal elements of the matrix
        std::vector<double> diagonal(N);

        // Create a vector to store the non-diagonal elements of the matrix
        std::vector<double> nonDiagonal(N);

        // Create a vector to store the right-hand side vector
        std::vector<double> rhs(N);

        // Create a vector to store the solution vector
        std::vector<double> solution(N);

        // Parallelize the computation of the diagonal and non-diagonal elements and the right-hand side vector
        hpx::parallel::for_loop(hpx::parallel::execution::par, 0, N, [&](size_t i) {
            double diagonalElement = 0.0;
            double nonDiagonalElement = 0.0;
            double rhsElement = 0.0;

            for (auto const& element : CSR[i]) {
                if (element.row == element.column) {
                    diagonalElement = element.value;
                } else {
                    nonDiagonalElement += element.value;
                }

                if (element.column == i) {
                    rhsElement += b[element.row];
                }
            }

            diagonal[i] = diagonalElement;
            nonDiagonal[i] = nonDiagonalElement;
            rhs[i] = rhsElement;
        });

        // Solve the system of equations using Gaussian elimination
        for (size_t i = 0; i < N; ++i) {
            double diagonalElement = diagonal[i];
            double nonDiagonalElement = nonDiagonal[i];
            double rhsElement = rhs[i];

            for (size_t j = i + 1; j < N; ++j) {
                double nonDiagonalElement2 = nonDiagonal[j];
                double diagonalElement2 = diagonal[j];
                double rhsElement2 = rhs[j];

                double factor = nonDiagonalElement2 / diagonalElement;
                diagonal[j] -= factor * nonDiagonalElement;
                nonDiagonal[j] -= factor * nonDiagonalElement2;
                rhs[j] -= factor * rhsElement;
            }

            solution[i] = rhsElement / diagonalElement;
        }

        // Copy the solution vector to the output vector
        x = solution;
}

