void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

        // Initialize x with zeros
        x.resize(N, 0);

        // Compute the diagonal elements of A
        std::vector<double> diag(N, 0);
        for (auto const& a : A) {
            if (a.row == a.column) {
                diag[a.row] = a.value;
            }
        }

        // Compute the off-diagonal elements of A
        std::vector<std::pair<size_t, double>> off_diag(N);
        for (auto const& a : A) {
            if (a.row!= a.column) {
                off_diag[a.row].first = a.column;
                off_diag[a.row].second = a.value;
            }
        }

        // Compute the solution x in parallel using HPX
        hpx::parallel::for_loop(hpx::parallel::execution::par, 0, N, [&](size_t i) {
            double sum = b[i];
            for (size_t j = 0; j < N; ++j) {
                if (j!= i) {
                    sum -= off_diag[j].second * x[off_diag[j].first];
                }
            }
            x[i] = sum / diag[i];
        });
}

