        // Sort the non-zero elements by row
        std::sort(nonZeroElements.begin(), nonZeroElements.end());

        // Use HPX to parallelize the computation
        hpx::parallel::for_loop(hpx::parallel::execution::par, 0, N, [&](size_t i) {
