        // Initialize Y with zeros
        Y.resize(M*N, 0.0);

        // Create a vector of vectors to hold the non-zero elements of X
        std::vector<std::vector<COOElement>> X_non_zero(K);
        for (auto const& x : X) {
            X_non_zero[x.column].push_back(x);
        }

        // Create a vector of vectors to hold the non-zero elements of A
        std::vector<std::vector<COOElement>> A_non_zero(M);
        for (auto const& a : A) {
            A_non_zero[a.row].push_back(a);
        }

        // Compute the matrix multiplication in parallel
        hpx::parallel::for_loop(hpx::parallel::execution::par, 0, M, 1, [&](size_t i) {
            for (size_t j = 0; j < N; ++j) {
                for (auto const& a : A_non_zero[i]) {
