        // Create a vector to store the result
        std::vector<double> result(M*N, 0.0);

        // Create a vector to store the non-zero elements of X
        std::vector<double> X_non_zero(K, 0.0);

        // Create a vector to store the non-zero elements of A
        std::vector<std::vector<double>> A_non_zero(M, std::vector<double>(K, 0.0));

        // Fill the non-zero elements of X
