void spmm(std::vector<COOElement> const& A, std::vector<COOElement> const& X, std::vector<double> &Y, size_t M, size_t K, size_t N) {

        // Initialize Y with zeros
        Y.resize(M*N, 0);

        // Create a map to store the non-zero elements of X
        std::map<std::pair<size_t, size_t>, double> X_map;
        for (auto const& x : X) {
            X_map[std::make_pair(x.row, x.column)] = x.value;
        }

        // Compute the matrix multiplication in parallel
        hpx::parallel::for_loop(hpx::parallel::execution::par, 0, M, 1, [&](size_t i) {
            for (size_t j = 0; j < N; ++j) {
                for (auto const& a : A) {
                    if (a.column == i) {
                        Y[i*N + j] += a.value * X_map[std::make_pair(a.row, j)];
                    }
                }
            }
        });
}

