void spmm(std::vector<COOElement> const& A, std::vector<COOElement> const& X, std::vector<double> &Y, size_t M, size_t K, size_t N) {

        // Initialize Y with zeros
        Y.resize(M*N, 0.0);

        // Create a map for each matrix
        std::map<std::pair<size_t, size_t>, double> A_map, X_map;
        for (auto const& a : A) A_map[std::make_pair(a.row, a.column)] = a.value;
        for (auto const& x : X) X_map[std::make_pair(x.row, x.column)] = x.value;

        // Compute the matrix multiplication in parallel
        hpx::parallel::for_loop(
            hpx::parallel::execution::par,
            0, M,
            [&](size_t i) {
                for (size_t j = 0; j < N; ++j) {
                    double sum = 0.0;
                    for (size_t k = 0; k < K; ++k) {
                        sum += A_map[std::make_pair(i, k)] * X_map[std::make_pair(k, j)];
                    }
                    Y[i*N + j] = sum;
                }
            }
        );
}

