generated_output:
void spmm(std::vector<COOElement> const& A, std::vector<COOElement> const& X, std::vector<double> &Y, size_t M, size_t K, size_t N) {

        // Create a vector of vectors to represent the sparse matrices
        std::vector<std::vector<std::pair<size_t, double>>> sparseA(M, std::vector<std::pair<size_t, double>>(K));
        std::vector<std::vector<std::pair<size_t, double>>> sparseX(K, std::vector<std::pair<size_t, double>>(N));

        // Populate the sparse matrices
        for (auto const& element : A) {
            sparseA[element.row][element.column] = std::make_pair(element.column, element.value);
        }
        for (auto const& element : X) {
            sparseX[element.row][element.column] = std::make_pair(element.column, element.value);
        }

        // Create a vector to hold the result
        Y.resize(M * N);

        // Compute the matrix multiplication in parallel using HPX
        hpx::parallel::for_loop(
            hpx::parallel::execution::par,
            0, M,
            [&](size_t i) {
                for (size_t j = 0; j < N; ++j) {
                    double sum = 0;
                    for (size_t k = 0; k < K; ++k) {
                        sum += sparseA[i][k].second * sparseX[k][j].second;
                    }
                    Y[i * N + j] = sum;
                }
            }
        );
}

