void spmm(std::vector<COOElement> const& A, std::vector<COOElement> const& X, std::vector<double> &Y, size_t M, size_t K, size_t N) {

        // Initialize Y with zeros
        Y.resize(M*N, 0);

        // Create a map for each row of A
        std::map<size_t, std::map<size_t, double>> A_map;
        for (auto const& a : A) {
            A_map[a.row][a.column] = a.value;
        }

        // Create a map for each column of X
        std::map<size_t, std::map<size_t, double>> X_map;
        for (auto const& x : X) {
            X_map[x.column][x.row] = x.value;
        }

        // Compute Y in parallel
        hpx::parallel::for_loop(hpx::parallel::execution::par, 0, M, [&](size_t i) {
            for (size_t j = 0; j < N; ++j) {
                double sum = 0;
                for (auto const& a : A_map[i]) {
                    sum += a.second * X_map[j][a.first];
                }
                Y[i*N + j] = sum;
            }
        });
}

