void spmm(std::vector<COOElement> const& A, std::vector<COOElement> const& X, std::vector<double> &Y, size_t M, size_t K, size_t N) {

generated_output:
void spmm(std::vector<COOElement> const& A, std::vector<COOElement> const& X, std::vector<double> &Y, size_t M, size_t K, size_t N) {

        // Create a vector to hold the results of the parallel computations
        std::vector<double> results(M * N, 0.0);

        // Use HPX to parallelize the computation
        hpx::parallel::for_loop(hpx::parallel::execution::par, 0, M, 1, [&](size_t i) {
            for (size_t j = 0; j < N; ++j) {
                double sum = 0.0;
                for (size_t k = 0; k < K; ++k) {
                    // Find the corresponding elements in A and X
                    auto itA = std::find_if(A.begin(), A.end(), [&](COOElement const& e) { return e.row == i && e.column == k; });
                    auto itX = std::find_if(X.begin(), X.end(), [&](COOElement const& e) { return e.row == k && e.column == j; });

                    // If the elements exist, multiply them and add to the sum
                    if (itA!= A.end() && itX!= X.end()) {
                        sum += itA->value * itX->value;
                    }
                }
                // Store the result in the results vector
                results[i * N + j] = sum;
            }
        });

        // Copy the results back to Y
        Y = std::move(results);
}

