generated_output:
void spmm(std::vector<COOElement> const& A, std::vector<COOElement> const& X, std::vector<double> &Y, size_t M, size_t K, size_t N) {

        // Initialize Y with zeros
        Y.resize(M*N, 0);

        // Create a vector of pairs to store the non-zero elements of Y
        std::vector<std::pair<size_t, double>> Y_non_zero;

        // Iterate over the non-zero elements of A
        for (auto const& a : A) {
            // Iterate over the non-zero elements of X
            for (auto const& x : X) {
                // If the column of A is equal to the row of X, then add the product of the values to the corresponding element in Y
                if (a.column == x.row) {
                    Y_non_zero.push_back({a.row*N + x.column, a.value * x.value});
                }
            }
        }

        // Sort the non-zero elements of Y by their indices
        std::sort(Y_non_zero.begin(), Y_non_zero.end());

        // Iterate over the sorted non-zero elements of Y
        for (size_t i = 0; i < Y_non_zero.size(); ++i) {
            // If the current element is not the same as the previous one, then update the corresponding element in Y
            if (i == 0 || Y_non_zero[i].first!= Y_non_zero[i-1].first) {
                Y[Y_non_zero[i].first] = Y_non_zero[i].second;
            } else {
                // If the current element is the same as the previous one, then add the value to the corresponding element in Y
                Y[Y_non_zero[i].first] += Y_non_zero[i].second;
            }
        }
}

