   X is a sparse KxN matrix in COO format. Y is a dense MxN matrix in row-major.
   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: A=[{0,0,-2}, {0,1,1}, {1,1,-1}] X=[{0,1,2}, {1,0,-1}]
   output: Y=[{-1,-4}, {1,0}]
*/
void spmm(std::vector<COOElement> const& A, std::vector<COOElement> const& X, std::vector<double> &Y, size_t M, size_t K, size_t N) {

generated_output:
void spmm(std::vector<COOElement> const& A, std::vector<COOElement> const& X, std::vector<double> &Y, size_t M, size_t K, size_t N) {

        // Create a vector of vectors to store the results of the multiplication
        std::vector<std::vector<double>> result(M, std::vector<double>(N, 0));

        // Create a vector of HPX futures to store the results of the multiplication
        std::vector<hpx::future<void>> futures;

        // Iterate over each element in A
        for (const auto& a : A) {
            // Iterate over each element in X
            for (const auto& x : X) {
                // If the columns of A and X match, multiply the values and add to the result
                if (a.column == x.row) {
                    // Create a HPX task to multiply the values and add to the result
                    futures.push_back(hpx::async([&result, a, x]() {
                        result[a.row][x.column] += a.value * x.value;
                    }));
                }
            }
        }

        // Wait for all tasks to complete
        hpx::wait_all(futures.begin(), futures.end());

        // Copy the result to Y
        for (size_t i = 0; i < M; ++i) {
            for (size_t j = 0; j < N; ++j) {
                Y[i * N + j] = result[i][j];
            }
        }
}

