generated_output:
void spmm(std::vector<COOElement> const& A, std::vector<COOElement> const& X, std::vector<double> &Y, size_t M, size_t K, size_t N) {

        // Initialize Y to zero
        Y.resize(M*N, 0);

        // Create a map to store the non-zero elements of X
        std::map<std::pair<size_t, size_t>, double> X_map;
        for (auto const& x : X) {
            X_map[std::make_pair(x.row, x.column)] = x.value;
        }

        // Compute Y in parallel using HPX
        hpx::parallel::for_loop(hpx::parallel::execution::par, 0, M, [&](size_t i) {
            for (size_t j = 0; j < N; ++j) {
                double sum = 0;
                for (auto const& a : A) {
                    if (a.row == i) {
                        auto it = X_map.find(std::make_pair(a.column, j));
                        if (it!= X_map.end()) {
                            sum += a.value * it->second;
                        }
                    }
                }
                Y[i*N + j] = sum;
            }
        });
}

