void spmm(std::vector<COOElement> const& A, std::vector<COOElement> const& X, std::vector<double> &Y, size_t M, size_t K, size_t N) {

        // This is a simple parallel implementation of the sparse matrix-matrix multiplication (SpMM) operation.
        // It uses the HPX parallel for_each algorithm to distribute the computation across multiple threads.
        // The algorithm assumes that the input vectors A and X are sorted by row and column indices.

        // Initialize the output matrix Y with zeros
        Y.resize(M*N, 0.0);

        // Define the HPX parallel for_each algorithm
        hpx::parallel::for_each(hpx::parallel::execution::par, 0, M, [&](size_t i) {
            for (size_t j = 0; j < N; ++j) {
                double sum = 0.0;
                size_t a_index = 0;
                size_t x_index = 0;

                while (a_index < A.size() && A[a_index].row == i) {
                    while (x_index < X.size() && X[x_index].column == j) {
                        if (A[a_index].column == X[x_index].row) {
                            sum += A[a_index].value * X[x_index].value;
                            ++a_index;
                            ++x_index;
                        } else if (A[a_index].column < X[x_index].row) {
                            ++a_index;
                        } else {
                            ++x_index;
                        }
                    }
                }

                Y[i*N + j] = sum;
            }
        });
}

