        // Compute y = alpha*A*x + beta*y in parallel
        hpx::parallel::for_each(hpx::parallel::execution::par, A.begin(), A.end(), [&](COOElement const& a) {
            y[a.row] += alpha * a.value * x[a.column];
        });
}

