void spmv(double alpha, std::vector<COOElement> const& A, std::vector<double> const& x, double beta, std::vector<double> &y, size_t M, size_t N) {

        // Sort the COO elements by row
        std::sort(A.begin(), A.end(), [](COOElement const& a, COOElement const& b) { return a.row < b.row; });

        // Create a vector to hold the partial sums for each row
        std::vector<double> partial_sums(M, 0.0);

        // Compute the partial sums in parallel
        hpx::parallel::for_loop(hpx::parallel::execution::par, 0, M, [&](size_t i) {
            for (auto const& element : A) {
                if (element.row == i) {
                    partial_sums[i] += element.value * x[element.column];
                }
            }
        });

        // Compute y = alpha*partial_sums + beta*y
        hpx::parallel::for_loop(hpx::parallel::execution::par, 0, M, [&](size_t i) {
            y[i] = alpha * partial_sums[i] + beta * y[i];
        });
}

