   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: alpha=0.5 beta=1.0 A=[{0,1,3}, {1,0,-1}] x=[-4, 2] y=[-1,1]
   output: y=[2, 3]
*/
void spmv(double alpha, std::vector<COOElement> const& A, std::vector<double> const& x, double beta, std::vector<double> &y, size_t M, size_t N) {

generated_output:
void spmv(double alpha, std::vector<COOElement> const& A, std::vector<double> const& x, double beta, std::vector<double> &y, size_t M, size_t N) {

        // Create a vector of HPX shared_ptr to store the result of each row computation
        std::vector<hpx::shared_future<double>> results(M);

        // Create a HPX parallel execution policy
        hpx::parallel::execution::parallel_executor exec;

        // For each row in the matrix
        for (size_t i = 0; i < M; ++i) {
            // Create a HPX task that computes the dot product of the row and the vector x
            auto task = hpx::async(exec, [i, &A, &x, M, N]() {
                double result = 0.0;
                for (size_t j = 0; j < N; ++j) {
                    for (auto const& element : A) {
                        if (element.row == i && element.column == j) {
                            result += element.value * x[j];
                            break;
                        }
                    }
                }
                return result;
            });

            // Store the future of the task in the results vector
            results[i] = task.share();
        }

        // Wait for all tasks to complete
        hpx::wait_all(results.begin(), results.end());

        // Update y with the results of the tasks
        for (size_t i = 0; i < M; ++i) {
            y[i] = alpha * results[i].get() + beta * y[i];
        }
}

