void spmv(double alpha, std::vector<COOElement> const& A, std::vector<double> const& x, double beta, std::vector<double> &y, size_t M, size_t N) {

        // Create a vector of HPX futures to hold the results of the computations
        std::vector<hpx::future<double>> results(M);

        // Loop over each row of the matrix
        for (size_t i = 0; i < M; ++i) {
            // Create a lambda function to compute the dot product of row i of A and x
            auto dot_product = [&A, &x, i](size_t j) {
                double sum = 0.0;
                for (auto const& element : A) {
                    if (element.row == i && element.column == j) {
                        sum += element.value * x[j];
                    }
                }
                return sum;
            };

            // Create a HPX task to compute the dot product for each column of row i
            results[i] = hpx::async(dot_product, hpx::parallel::execution::par, hpx::util::iota_iterator(0), hpx::util::iota_iterator(N));
        }

        // Wait for all the tasks to complete
        hpx::wait_all(results);

        // Update y with the results of the computations
        for (size_t i = 0; i < M; ++i) {
            y[i] = alpha * results[i].get() + beta * y[i];
        }
}

