void spmv(double alpha, std::vector<COOElement> const& A, std::vector<double> const& x, double beta, std::vector<double> &y, size_t M, size_t N) {

        // Create a vector of HPX futures to hold the results of each row operation
        std::vector<hpx::future<double>> results(M);

        // Iterate over each row of the matrix
        for (size_t i = 0; i < M; ++i) {
            // Create a lambda function to compute the dot product of the ith row of A and x
            auto row_op = [i, &A, &x, alpha, beta, &y](size_t row) {
                double sum = 0.0;
                for (auto const& element : A) {
                    if (element.row == row) {
                        sum += element.value * x[element.column];
                    }
                }
                return alpha * sum + beta * y[row];
            };

            // Schedule the operation to be executed on a worker thread
            results[i] = hpx::async(row_op, i);
        }

        // Wait for all operations to complete and store the results in y
        for (size_t i = 0; i < M; ++i) {
            y[i] = results[i].get();
        }
}

