void spmv(double alpha, std::vector<COOElement> const& A, std::vector<double> const& x, double beta, std::vector<double> &y, size_t M, size_t N) {

        // Sort the COO elements by row
        std::sort(A.begin(), A.end(), [](COOElement const& a, COOElement const& b) {
            return a.row < b.row;
        });

        // Initialize y with beta*y
        std::transform(y.begin(), y.end(), y.begin(), [beta](double val) {
            return beta * val;
        });

        // Compute y = alpha*A*x + beta*y in parallel
        hpx::parallel::for_loop(hpx::parallel::execution::par, 0, M, [&](size_t i) {
            double sum = 0.0;
            for (size_t j = 0; j < N; ++j) {
                auto it = std::lower_bound(A.begin(), A.end(), COOElement{i, j, 0.0}, [](COOElement const& a, COOElement const& b) {
                    return a.row < b.row || (a.row == b.row && a.column < b.column);
                });
                if (it!= A.end() && it->row == i && it->column == j) {
                    sum += it->value * x[j];
                }
            }
            y[i] = alpha * sum + y[i];
        });
}

