generated_output:
void spmv(double alpha, std::vector<COOElement> const& A, std::vector<double> const& x, double beta, std::vector<double> &y, size_t M, size_t N) {

        // Create a vector of HPX futures to store the results of each row computation
        std::vector<hpx::future<double>> results(M);

        // Iterate over each row of the matrix
        for (size_t i = 0; i < M; ++i) {
            // Create a HPX task to compute the dot product of the ith row of A and x
            results[i] = hpx::async([i, &A, &x, M, N]() {
                double result = 0.0;
                for (size_t j = 0; j < N; ++j) {
                    for (auto const& element : A) {
                        if (element.row == i && element.column == j) {
                            result += element.value * x[j];
                            break;
                        }
                    }
                }
                return result;
            });
        }

        // Wait for all tasks to complete and store the results in y
        for (size_t i = 0; i < M; ++i) {
            y[i] = beta * y[i] + alpha * results[i].get();
        }
}

