void spmv(double alpha, std::vector<COOElement> const& A, std::vector<double> const& x, double beta, std::vector<double> &y, size_t M, size_t N) {

        // Create a vector of HPX futures
        std::vector<hpx::future<double>> futures;

        // Iterate over each row of the matrix
        for (size_t i = 0; i < M; ++i) {
            // Create a lambda function that computes the dot product of the ith row of A and x
            auto dot_product = [&A, &x, i]() {
                double result = 0.0;
                for (auto const& element : A) {
                    if (element.row == i) {
                        result += element.value * x[element.column];
                    }
                }
                return result;
            };

            // Schedule the lambda function to be executed on a worker thread
            futures.push_back(hpx::async(dot_product));
        }

        // Wait for all futures to complete and get their results
        for (size_t i = 0; i < M; ++i) {
            y[i] = alpha * futures[i].get() + beta * y[i];
        }
}

