void spmv(double alpha, std::vector<COOElement> const& A, std::vector<double> const& x, double beta, std::vector<double> &y, size_t M, size_t N) {

        // Create a vector of HPX futures to store the results of the computations
        std::vector<hpx::future<double>> results(M);

        // Loop over the rows of the matrix
        for (size_t i = 0; i < M; ++i) {
            // Create a HPX lambda function to compute the dot product of the i-th row of A and x
            auto dot_product = [&A, &x, i](size_t row) {
                double sum = 0.0;
                for (auto const& element : A) {
                    if (element.row == row) {
                        sum += element.value * x[element.column];
                    }
                }
                return sum;
            };

            // Schedule the computation to run on a worker thread
            results[i] = hpx::async(dot_product, i);
        }

        // Wait for all computations to complete
        hpx::wait_all(results.begin(), results.end());

        // Update y
        for (size_t i = 0; i < M; ++i) {
            y[i] = alpha * results[i].get() + beta * y[i];
        }
}

