void spmv(double alpha, std::vector<COOElement> const& A, std::vector<double> const& x, double beta, std::vector<double> &y, size_t M, size_t N) {

        // Create a vector to hold the partial results
        std::vector<double> partial_results(M, 0.0);

        // Use HPX to parallelize the computation
        hpx::parallel::for_loop(hpx::parallel::execution::par, 0, M, [&](size_t i) {
            for (auto const& element : A) {
                if (element.row == i) {
                    partial_results[i] += element.value * x[element.column];
                }
            }
        });

        // Combine the partial results
        hpx::parallel::for_loop(hpx::parallel::execution::par, 0, M, [&](size_t i) {
            y[i] = alpha * partial_results[i] + beta * y[i];
        });
}

