void spmv(double alpha, std::vector<COOElement> const& A, std::vector<double> const& x, double beta, std::vector<double> &y, size_t M, size_t N) {

        // Create a vector of HPX shared_ptr to store the results of the computations
        std::vector<hpx::shared_future<double>> results(M);

        // Iterate over each row of the matrix
        for (size_t i = 0; i < M; ++i) {
            // Launch a HPX task for each row
            results[i] = hpx::async([i, &A, &x, M, N, alpha, beta, &y]() {
                double sum = 0.0;
                // Iterate over each element in the row
                for (auto const& element : A) {
                    // If the element is in the current row, add its value to the sum
                    if (element.row == i) {
                        sum += element.value * x[element.column];
                    }
                }
                // Return the result
                return alpha * sum + beta * y[i];
            });
        }

        // Wait for all tasks to complete and get the results
        for (size_t i = 0; i < M; ++i) {
            y[i] = results[i].get();
        }
}

