/* Compute z = alpha*x+y where x and y are sparse vectors. Store the result in the dense vector z.
   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: x=[{5, 12}, {8, 3}, {12, -1}], y=[{3, 1}, {5, -2}, {7, 1}, {8, -3}], alpha=1
   output: z=[0, 0, 0, 1, 0, 10, 0, 1, 0, 0, 0, 0, -1]
*/
void sparseAxpy(double alpha, std::vector<Element> const& x, std::vector<Element> const& y, std::vector<double> &z) {

generated_output:
void sparseAxpy(double alpha, std::vector<Element> const& x, std::vector<Element> const& y, std::vector<double> &z) {

        // Create a parallel execution policy
        hpx::parallel::execution::parallel_executor exec;

        // Compute the size of the dense vector z
        size_t z_size = z.size();

        // Create a vector of pairs to store the results of the parallel computation
        std::vector<std::pair<size_t, double>> results(z_size);

        // Compute the parallel computation
        hpx::parallel::transform(exec, x.begin(), x.end(), y.begin(), results.begin(),
            [alpha, z_size](Element const& x_elem, Element const& y_elem) {
                size_t index = x_elem.index;
                double value = alpha * x_elem.value + y_elem.value;
                return std::make_pair(index, value);
            });

        // Sort the results by index
        std::sort(results.begin(), results.end(),
            [](std::pair<size_t, double> const& a, std::pair<size_t, double> const& b) {
                return a.first < b.first;
            });

        // Update the dense vector z with the results
        for (size_t i = 0; i < z_size; ++i) {
            if (results[i].first == i) {
                z[i] = results[i].second;
            }
        }
}

