void sparseAxpy(double alpha, std::vector<Element> const& x, std::vector<Element> const& y, std::vector<double> &z) {

        // Create a HPX parallel execution policy
        hpx::parallel::execution::parallel_executor exec;

        // Compute the size of the dense vector z
        size_t size_z = z.size();

        // Compute the size of the sparse vectors x and y
        size_t size_x = x.size();
        size_t size_y = y.size();

        // Initialize the sparse vectors x and y
        std::vector<Element> x_copy(x);
        std::vector<Element> y_copy(y);

        // Sort the sparse vectors x and y by their indices
        std::sort(x_copy.begin(), x_copy.end(), [](const Element& a, const Element& b) {
            return a.index < b.index;
        });
        std::sort(y_copy.begin(), y_copy.end(), [](const Element& a, const Element& b) {
            return a.index < b.index;
        });

        // Compute the result in parallel
        hpx::parallel::for_each(exec, hpx::parallel::execution::par, 0, size_z, [&](size_t i) {
