#include <hpx/hpx_main.hpp>

struct Element {
	size_t index;
  double value;
};

/* Compute z = alpha*x+y where x and y are sparse vectors. Store the result in the dense vector z.
   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: x=[{5, 12}, {8, 3}, {12, -1}], y=[{3, 1}, {5, -2}, {7, 1}, {8, -3}], alpha=1
   output: z=[0, 0, 0, 1, 0, 10, 0, 1, 0, 0, 0, 0, -1]
*/
void sparseAxpy(double alpha, std::vector<Element> const& x, std::vector<Element> const& y, std::vector<double> &z) {

generated_output:
void sparseAxpy(double alpha, std::vector<Element> const& x, std::vector<Element> const& y, std::vector<double> &z) {

        // Create a vector of pairs to hold the results of the HPX parallel operations
        std::vector<hpx::future<std::pair<size_t, double>>> results;

        // Iterate over the elements of x and y in parallel
        for (auto const& x_elem : x) {
            for (auto const& y_elem : y) {
                // If the indices match, add the values together and multiply by alpha
                if (x_elem.index == y_elem.index) {
                    results.push_back(hpx::async([=]() {
                        return std::make_pair(x_elem.index, alpha * (x_elem.value + y_elem.value));
                    }));
                }
            }
        }

        // Wait for all the futures to complete and collect the results
        for (auto& result : results) {
            auto pair = result.get();
            if (pair.first < z.size()) {
                z[pair.first] = pair.second;
            }
        }
}

