void sparseAxpy(double alpha, std::vector<Element> const& x, std::vector<Element> const& y, std::vector<double> &z) {

        // Create a vector of pairs to store the result
        std::vector<std::pair<size_t, double>> result;

        // Use HPX to compute in parallel
        hpx::parallel::for_each(hpx::parallel::execution::par,
                                x.begin(), x.end(),
                                [&](Element const& e) {
                                    // Find the corresponding element in y
                                    auto it = std::find_if(y.begin(), y.end(),
                                                           [&](Element const& f) { return f.index == e.index; });

                                    // If found, add the values
