        // Create a vector of pairs to hold the results
        std::vector<std::pair<size_t, double>> results;

        // Use HPX to parallelize the computation
        hpx::parallel::for_loop(hpx::parallel::execution::par, 0, x.size(), 0, [&](size_t i) {
