            }

            // Add the result to the vector
            results.push_back({index, value});
        });

        // Sort the results by index
        std::sort(results.begin(), results.end(), [](const std::pair<size_t, double>& a, const std::pair<size_t, double>& b) {
            return a.first < b.first;
        });

        // Update z with the results
        for (const auto& result : results) {
            z[result.first] = result.second;
