void luFactorize(std::vector<COOElement> const& A, std::vector<double> &L, std::vector<double> &U, size_t N) {

        // This is a simple sequential implementation of LU decomposition.
        // In a parallel implementation, you would need to use HPX parallel algorithms.

        // Initialize L and U matrices
        for (size_t i = 0; i < N; ++i) {
            L[i*N + i] = 1.0;
            U[i*N + i] = A[i*N + i].value;
            for (size_t j = i + 1; j < N; ++j) {
                L[j*N + i] = A[j*N + i].value / U[i*N + i];
                U[i*N + j] = A[i*N + j].value;
            }
        }

        // Update U matrix
        for (size_t i = 0; i < N; ++i) {
            for (size_t j = i + 1; j < N; ++j) {
                for (size_t k = j; k < N; ++k) {
                    U[i*N + k] -= L[j*N + i] * U[j*N + k];
                }
            }
        }
}

