void luFactorize(std::vector<COOElement> const& A, std::vector<double> &L, std::vector<double> &U, size_t N) {

        // Initialize L and U to be identity matrices
        for (size_t i = 0; i < N; ++i) {
            L.push_back(1.0);
            U.push_back(0.0);
        }

        // Iterate over the elements of A
        for (size_t i = 0; i < A.size(); ++i) {
            size_t row = A[i].row;
            size_t column = A[i].column;
            double value = A[i].value;

            // Compute the value of L[i][j] for all j > i
            for (size_t j = i; j < N; ++j) {
                double sum = 0.0;
                for (size_t k = 0; k < j; ++k) {
                    sum += L[row * N + k] * U[k * N + column];
                }
                L[row * N + j] = (j == column)? 1.0 : (value - sum) / U[column * N + column];
            }

            // Compute the value of U[i][j] for all j >= i
            for (size_t j = i; j < N; ++j) {
                double sum = 0.0;
                for (size_t k = 0; k < j; ++k) {
                    sum += L[row * N + k] * U[k * N + j];
                }
                U[row * N + j] = (j == column)? value - sum : (value - sum) / L[row * N + row];
            }
        }
}

