void luFactorize(std::vector<COOElement> const& A, std::vector<double> &L, std::vector<double> &U, size_t N) {

        // Implementation of LU factorization using HPX

        // Create a parallel execution policy
        hpx::parallel::execution::parallel_executor exec;

        // Initialize L and U with zeros
        L.resize(N*N, 0);
        U.resize(N*N, 0);

        // Fill L and U with the elements of A
        hpx::parallel::for_each(exec, A.begin(), A.end(), [&](COOElement const& element) {
            size_t row = element.row;
            size_t column = element.column;
            double value = element.value;

            if (row == column) {
                // Diagonal elements of U
                U[row*N + column] = value;
            } else if (row < column) {
                // Lower triangular elements of L
                L[row*N + column] = value;
            } else {
                // Upper triangular elements of U
                U[row*N + column] = value;
            }
        });

        // Compute the elements of L and U
        for (size_t i = 0; i < N; ++i) {
            for (size_t j = i+1; j < N; ++j) {
                double sum = L[i*N + j];
                for (size_t k = 0; k < j; ++k) {
                    sum -= L[i*N + k] * U[k*N + j];
                }
                L[i*N + j] = sum;
            }

            for (size_t j = i; j < N; ++j) {
                if (i == j) {
                    continue;
                }
                double sum = U[i*N + j];
                for (size_t k = 0; k < i; ++k) {
                    sum -= L[i*N + k] * U[k*N + j];
                }
                U[i*N + j] = sum / L[i*N + i];
            }
        }
}

