void luFactorize(std::vector<COOElement> const& A, std::vector<double> &L, std::vector<double> &U, size_t N) {

        // Implement the LU factorization algorithm here
        // This is a simple sequential implementation
        // You can use HPX to parallelize this algorithm

        // Initialize L and U as identity matrices
        for (size_t i = 0; i < N; ++i) {
            L.push_back(1.0);
            U.push_back(0.0);
        }

        // Iterate over each element in A
        for (size_t i = 0; i < A.size(); ++i) {
            size_t row = A[i].row;
            size_t column = A[i].column;
            double value = A[i].value;

            // Update L and U
            for (size_t j = 0; j < N; ++j) {
                if (j < row) {
                    L[row * N + j] += L[column * N + j] * value;
                } else if (j > row) {
                    U[row * N + j] += L[column * N + j] * value;
                }
            }
            U[row * N + row] = value;
        }

        // Convert L and U to COO format
        for (size_t i = 0; i < N; ++i) {
            for (size_t j = 0; j < N; ++j) {
                if (i == j) {
                    L.push_back({i, j, 1.0});
                } else if (i < j) {
                    L.push_back({i, j, L[i * N + j]});
                } else {
                    U.push_back({i, j, U[i * N + j]});
                }
            }
        }
}

