void luFactorize(std::vector<COOElement> const& A, std::vector<double> &L, std::vector<double> &U, size_t N) {

        // Initialize L and U with zeros
        L.resize(N*N, 0);
        U.resize(N*N, 0);

        // Fill L and U with the values from A
        for (auto const& element : A) {
            L[element.row * N + element.column] = element.value;
            U[element.row * N + element.column] = element.value;
        }

        // Perform the LU factorization
        for (size_t i = 0; i < N; ++i) {
            for (size_t k = i; k < N; ++k) {
                double sum = 0;
                for (size_t j = 0; j < i; ++j) {
                    sum += L[i * N + j] * U[j * N + k];
                }
                L[i * N + k] = U[i * N + k] - sum;
            }

            for (size_t k = i; k < N; ++k) {
                if (i == k) {
                    U[i * N + k] = 1;
                } else {
                    double sum = 0;
                    for (size_t j = 0; j < i; ++j) {
                        sum += L[k * N + j] * U[j * N + i];
                    }
                    U[k * N + i] = (L[k * N + i] - sum) / L[i * N + i];
                }
            }
        }
}

