        L.resize(N*N, 0);
        U.resize(N*N, 0);

        // Loop over the elements of A
        for (size_t i = 0; i < A.size(); ++i) {
            size_t row = A[i].row;
            size_t column = A[i].column;
            double value = A[i].value;

            // Compute the L and U matrices
            if (row == column) {
                U[row*N + column] = value;
