            for(size_t j = i; j < N; ++j) {
                double sum = 0;
                for(size_t k = 0; k < i; ++k) {
                    sum += L[i*N + k] * U[k*N + j];
                }
                U[i*N + j] = A[i*N + j].value - sum;
            }
        });
}

