void luFactorize(std::vector<COOElement> const& A, std::vector<double> &L, std::vector<double> &U, size_t N) {

        // Initialize L and U with zeros
        L.resize(N*N, 0);
        U.resize(N*N, 0);

        // Fill L and U with the values from A
        for (auto const& element : A) {
            size_t row = element.row;
            size_t column = element.column;
            double value = element.value;

            if (row == column) {
                // Diagonal elements of L are 1
                L[row*N + column] = 1;
            } else if (row < column) {
                // Lower triangle elements of L
                L[row*N + column] = value;
            } else {
                // Upper triangle elements of U
                U[row*N + column] = value;
            }
        }

        // Compute L and U in parallel using HPX
        hpx::parallel::for_loop(hpx::parallel::execution::par, 0, N, [&](size_t i) {
            for (size_t j = i; j < N; ++j) {
                double sum = 0;
                for (size_t k = 0; k < i; ++k) {
                    sum += L[i*N + k] * U[k*N + j];
                }
                U[i*N + j] -= sum;
            }

            for (size_t j = i; j < N; ++j) {
                if (i == j) {
                    L[i*N + j] = 1;
                } else {
                    double sum = 0;
                    for (size_t k = 0; k < i; ++k) {
                        sum += L[j*N + k] * U[k*N + i];
                    }
                    L[j*N + i] = (U[i*N + i] == 0)? 0 : (A[j*N + i] - sum) / U[i*N + i];
                }
            }
        });
}

