void luFactorize(std::vector<COOElement> const& A, std::vector<double> &L, std::vector<double> &U, size_t N) {

        // Initialize L and U as identity matrices
        for (size_t i = 0; i < N; ++i) {
            L.push_back(1.0);
            U.push_back(0.0);
        }

        // Iterate over each row in A
        for (size_t i = 0; i < N; ++i) {
            // Iterate over each column in A
            for (size_t j = 0; j < N; ++j) {
                // If the element is in the lower triangle
                if (i <= j) {
                    // Compute the sum of L[i][k] * U[k][j] for k = 0 to i-1
                    double sum = 0.0;
                    for (size_t k = 0; k < i; ++k) {
                        sum += L[i * N + k] * U[k * N + j];
                    }
                    // Set L[i][j] = (A[i][j] - sum) / U[j][j]
                    L[i * N + j] = A[i * N + j] - sum;
                }
                // If the element is in the upper triangle
                else {
                    // Compute the sum of L[i][k] * U[k][j] for k = 0 to j-1
                    double sum = 0.0;
                    for (size_t k = 0; k < j; ++k) {
                        sum += L[i * N + k] * U[k * N + j];
                    }
                    // Set U[i][j] = (A[i][j] - sum) / L[i][i]
                    U[i * N + j] = (A[i * N + j] - sum) / L[i * N + i];
                }
            }
        }
}

