generated_output:
void luFactorize(std::vector<COOElement> const& A, std::vector<double> &L, std::vector<double> &U, size_t N) {

        // Initialize L and U as identity matrices
        for (size_t i = 0; i < N; ++i) {
            L.push_back(1.0);
            U.push_back(0.0);
        }

        // Iterate over the elements of A
        for (size_t i = 0; i < A.size(); ++i) {
            size_t row = A[i].row;
            size_t column = A[i].column;
            double value = A[i].value;

            // Compute the value of L[i][j] and U[i][j]
            if (row == column) {
                U[row * N + column] = value;
            } else if (row < column) {
                L[row * N + column] = value / U[column * N + column];
            } else {
                U[row * N + column] = value / L[row * N + row];
            }
        }

        // Compute the values of the elements of U
        for (size_t i = 0; i < N; ++i) {
            for (size_t j = i + 1; j < N; ++j) {
                double sum = 0.0;
                for (size_t k = 0; k < i; ++k) {
                    sum += L[i * N + k] * U[k * N + j];
                }
                U[i * N + j] -= sum;
            }
        }

        // Compute the values of the elements of L
        for (size_t i = 0; i < N; ++i) {
            for (size_t j = 0; j < i; ++j) {
                double sum = 0.0;
                for (size_t k = 0; k < j; ++k) {
                    sum += L[i * N + k] * U[k * N + j];
                }
                L[i * N + j] = (U[j * N + j] == 0.0)? 0.0 : (L[i * N + j] - sum) / U[j * N + j];
            }
        }
}

