void luFactorize(std::vector<COOElement> const& A, std::vector<double> &L, std::vector<double> &U, size_t N) {

        // Initialize L and U as identity matrices
        for (size_t i = 0; i < N; ++i) {
            L.push_back(1);
            U.push_back(0);
        }

        // Factorize A into L and U
        for (size_t i = 0; i < N; ++i) {
            for (size_t j = 0; j < N; ++j) {
                if (i == j) {
                    U[i*N + j] = 1;
                } else if (i < j) {
                    double sum = 0;
                    for (size_t k = 0; k < i; ++k) {
                        sum += L[i*N + k] * U[k*N + j];
                    }
                    L[i*N + j] = (A[i*N + j] - sum) / U[i*N + i];
                } else {
                    double sum = 0;
                    for (size_t k = 0; k < j; ++k) {
                        sum += L[i*N + k] * U[k*N + j];
                    }
                    U[i*N + j] = A[i*N + j] - sum;
                }
            }
        }
}

