void luFactorize(std::vector<COOElement> const& A, std::vector<double> &L, std::vector<double> &U, size_t N) {

generated_output:
void luFactorize(std::vector<COOElement> const& A, std::vector<double> &L, std::vector<double> &U, size_t N) {

        // Initialize L and U to identity matrices
        for (size_t i = 0; i < N; ++i) {
            L.push_back(1.0);
            U.push_back(0.0);
        }

        // Iterate over each element in A
        for (size_t i = 0; i < A.size(); ++i) {
            size_t row = A[i].row;
            size_t column = A[i].column;
            double value = A[i].value;

            // Compute the value for L
            if (row == column) {
                L[row * N + column] = 1.0;
            } else if (row < column) {
                L[row * N + column] = value / U[row * N + row];
            }

            // Compute the value for U
            if (row <= column) {
                U[row * N + column] = value;
            }

            // Subtract the row of L times the column of U from the rest of the row
            for (size_t j = row + 1; j < N; ++j) {
                double l_value = L[j * N + column];
                U[row * N + j] -= l_value * U[row * N + column];
                L[j * N + column] = 0.0;
            }
        }
}

