void luFactorize(std::vector<COOElement> const& A, std::vector<double> &L, std::vector<double> &U, size_t N) {

        // Implementation of LU factorization using HPX
        // This is a simple example and may not be efficient for large sparse matrices

        // Initialize L and U to identity matrices
        for (size_t i = 0; i < N; ++i) {
            L.push_back(1.0);
            U.push_back(0.0);
        }

        // Parallelize the computation of L and U
        hpx::parallel::for_loop(hpx::parallel::execution::par, 0, N, [&](size_t i) {
            for (size_t j = 0; j < N; ++j) {
                if (i == j) {
                    U[i * N + j] = 1.0;
                } else if (i < j) {
                    double sum = 0.0;
                    for (size_t k = 0; k < i; ++k) {
