void luFactorize(std::vector<COOElement> const& A, std::vector<double> &L, std::vector<double> &U, size_t N) {

        // Initialize L and U with zeros
        L.resize(N*N, 0);
        U.resize(N*N, 0);

        // Factorize A into L and U
        for (size_t i = 0; i < N; ++i) {
            // Compute U
            U[i*N + i] = 1;
            for (size_t k = i; k < N; ++k) {
                double sum = 0;
                for (size_t j = 0; j < i; ++j) {
                    sum += L[i*N + j] * U[j*N + k];
                }
                L[i*N + k] = A[i*N + k] - sum;
            }

            // Compute L
            for (size_t k = i+1; k < N; ++k) {
                double sum = 0;
                for (size_t j = 0; j < i; ++j) {
                    sum += L[k*N + j] * U[j*N + i];
                }
                U[i*N + k] = (A[i*N + k] - sum) / L[i*N + i];
            }
        }
}

